CHUNK = 1024 * 1024
KEEP_PARTS_WAIT = 900.0   # seconds a start may take (leveling, heat-up) before the skip commands get through
KEEP_PARTS_POLL = 1.0
CC2_UPLOAD_TRIES = 5      # per piece, when the printer says busy (HTTP 429) or drops the connection
