class ElegooCC2:
    kind = KIND_CC2

    def __init__(self, address, access_code="", timeout=6, mqtt_port=1883):
        self.address = host_of(address)
        self.host = self.address.split(":")[0]
        self.token = access_code or "123456"
        self.timeout = timeout
        self.mqtt_port = int(mqtt_port or 1883)
        self._sn = None

    # -- HTTP -------------------------------------------------------------------------
    def system_info(self):
        url = "http://%s/system/info?X-Token=%s" % (self.address, urllib.parse.quote(self.token))
        reply = http_json(url, headers={"X-Token": self.token, "Accept": "application/json"}, timeout=self.timeout)
        if reply.get("error_code", -1) != 0:
            raise FarmError("Printer returned an error: %s (%s)" % (reply.get("message", "unknown"), reply.get("error_code")))
        info = reply.get("system_info") or {}
        if not info.get("sn"):
            raise FarmError("Printer did not report a serial number")
        self._sn = info["sn"]
        return info

    def serial(self):
        if not self._sn:
            self.system_info()
        return self._sn

    def identify(self):
        info = self.system_info()
        return {"model": info.get("machine_model", ""), "name": info.get("hostname", ""), "serial": info.get("sn", ""),
                "firmware": (info.get("software_version") or {}).get("ota_version", "")}

    def upload(self, path, filename, progress=None, cancelled=None):
        """Send the file in 1 MB pieces over ONE kept-open connection, as OrcaSlicer's own ElegooLink
        client does. The printer answers HTTP 429 once a few connections arrive within seconds, so a
        connection per piece fails on any plate larger than about 3 MB (seen on a 23 MB plate; the
        same plate took 6 s over one connection). A 429 or a dropped connection is retried on a new
        connection after a pause, resending the same piece."""
        filename = safe_filename(filename)
        size = os.path.getsize(path)
        if size <= 0:
            raise FarmError("The G-code file is empty")
        md5 = file_md5(path)
        host, port, target = _split_url("http://%s/upload" % self.address)
        connection, sent = None, 0
        try:
            with open(path, "rb") as handle:
                while sent < size:
                    chunk = handle.read(CHUNK)
                    if not chunk:
                        raise FarmError("The G-code file changed while uploading")
                    headers = {
                        "Accept": "application/json",
                        "Content-Type": "application/octet-stream",
                        "Content-Length": str(len(chunk)),
                        "Content-Range": "bytes %d-%d/%d" % (sent, sent + len(chunk) - 1, size),
                        "X-File-Name": filename,   # raw, exactly as OrcaSlicer's own ElegooLink client sends it
                        "X-File-MD5": md5,
                        "X-Token": self.token,
                    }
                    for attempt in range(CC2_UPLOAD_TRIES):
                        if cancelled is not None and cancelled():
                            raise FarmError("Upload cancelled")
                        status, raw, problem = 0, b"", ""
                        try:
                            if connection is None:
                                connection = http.client.HTTPConnection(host, port, timeout=180)
                            connection.request("PUT", target, body=chunk, headers=headers)
                            response = connection.getresponse()
                            status, raw = response.status, response.read()
                        except PermissionError:
                            raise
                        except (socket.timeout, TimeoutError):
                            problem = "timed out"
                        except (OSError, http.client.HTTPException) as error:
                            problem = str(getattr(error, "strerror", None) or error)
                        if status == 200:
                            break
                        if status in (401, 403):
                            raise FarmError("Access denied (HTTP %d). Check the access code or API key." % status)
                        # Busy or dropped: start over on a fresh connection after a growing pause.
                        if connection is not None:
                            connection.close()
                            connection = None
                        if attempt == CC2_UPLOAD_TRIES - 1 or (status and status != 429):
                            raise FarmError("Upload failed: %s" % (("HTTP %d from printer" % status) if status else
                                                                   ("cannot reach printer: " + problem)))
                        time.sleep(CC2_UPLOAD_PAUSE * (attempt + 1))
                    try:
                        reply = json.loads(raw.decode("utf-8", errors="replace")) if raw else {}
                    except ValueError:
                        reply = {}
                    _cc2_check(reply if isinstance(reply, dict) and "error_code" in reply else {"error_code": -1}, "Upload failed")
                    sent += len(chunk)
                    if progress is not None:
                        progress(sent, size)
        finally:
            if connection is not None:
                connection.close()
        return filename

    # -- MQTT -------------------------------------------------------------------------
    def _session(self):
        return _CC2Session(self.host, self.serial(), self.token, self.timeout, self.mqtt_port)

    def status(self):
        with self._session() as session:
            out = normalize_cc2_status(session.request(CC2_GET_BASIC_INFO, {}))
            out["tools"] = [{key: roll[key] for key in ("slot", "color", "type", "loaded")} for roll in self._rolls(session)]
            return out

    def _rolls(self, session):
        """The rolls in the Canvas unit, or [] for a printer without one. A printer that does not
        answer the question is not asked again by this window."""
        if self.host in _CC2_NO_ROLLS:
            return []
        try:
            return cc2_rolls(session.request(CC2_GET_CANVAS, {}, timeout=5))
        except FarmError:
            _CC2_NO_ROLLS.add(self.host)
            return []

    def raw_status(self):
        with self._session() as session:
            return session.request(CC2_GET_BASIC_INFO, {})

    def list_files(self, limit=50):
        with self._session() as session:
            reply = session.request(CC2_GET_FILE_LIST, {"storage_media": "local", "offset": 0, "limit": limit}, timeout=15)
        _cc2_check(reply, "Could not list files")
        return [entry.get("filename", "") for entry in reply.get("file_list") or []]

    def list_stored(self):
        """Every stored file as {name, modified, size}. The printer hands out 100 per request."""
        files = []
        with self._session() as session:
            while len(files) < CC2_MAX_LISTED:
                reply = session.request(CC2_GET_FILE_LIST, {"storage_media": "local", "offset": len(files), "limit": 100}, timeout=15)
                _cc2_check(reply, "Could not list files")
                page = [entry for entry in reply.get("file_list") or [] if isinstance(entry, dict)]
                files += [{"name": str(entry.get("filename") or ""), "modified": float(entry.get("create_time") or 0),
                           "size": int(entry.get("size") or 0)}
                          for entry in page if entry.get("type", "file") == "file" and entry.get("filename")]
                total = reply.get("total")
                if not page or len(page) < 100 or (isinstance(total, int) and len(files) >= total):
                    break
        return files

    def delete_files(self, names, progress=None, cancelled=None):
        """Delete stored files in one session, a few per request. Returns how many requests of
        names were sent; the printer answers "ok" even for a file it did not delete, so the caller
        lists again to see what is really gone."""
        names, done = list(names), 0
        with self._session() as session:
            for start in range(0, len(names), CC2_DELETE_BATCH):
                if cancelled is not None and cancelled():
                    break
                batch = names[start:start + CC2_DELETE_BATCH]
                reply = session.request(CC2_DELETE_FILE, {"storage_media": "local", "file_path": batch}, timeout=20)
                _cc2_check(reply, "Could not delete files")
                done += len(batch)
                if progress is not None:
                    progress(done, len(names))
        return done

    def delete_file(self, filename):
        with self._session() as session:
            # The printer takes a list of paths; a bare string is rejected as "invalid parameter".
            reply = session.request(CC2_DELETE_FILE, {"storage_media": "local", "file_path": [filename]})
        _cc2_check(reply, "Could not delete file")

    def list_videos(self):
        """The time-lapses the printer holds, one per finished print in its history that has frames
        or a video: [{name, modified, size, video, task, layers}]. size is 0 until a video was
        exported; layers is the print's layer count, or 0 when its G-code is no longer stored."""
        with self._session() as session:
            reply = session.request(CC2_GET_HISTORY, {}, timeout=15)
        _cc2_check(reply, "Could not read the print history")
        found = cc2_recordings(reply.get("history_task_list") or [])
        self._add_layers(found)
        return found

    def _add_layers(self, recordings):
        """Fill in each recording's layer count from its G-code file, which the printer makes one
        frame per layer from. Counts are read while the G-code is still there (a later G-code
        clean-up removes it) and saved in the plugin's storage folder, so they outlast a restart."""
        known = _cc2_layer_cache(self.host)
        missing = [item for item in recordings if item["task"] not in known and item.get("gcode")]
        if missing:
            try:
                stored = {entry["name"] for entry in self.list_stored()}
                with self._session() as session:
                    for item in missing:
                        if item["gcode"] not in stored:
                            known[item["task"]] = 0
                            continue
                        reply = session.request(CC2_GET_FILE_DETAIL, {"storage_media": "local", "filename": item["gcode"]}, timeout=10)
                        layers = reply.get("layer") if reply.get("error_code", 0) in (0, None) else None
                        known[item["task"]] = layers if isinstance(layers, int) and 0 < layers < CC2_MAX_LAYERS else 0
            except FarmError:
                pass      # the ones not read yet are tried at the next listing
        for item in recordings:
            item["layers"] = known.get(item["task"], 0)
        if missing:
            # Only the prints still in the history are kept, so the file stays small.
            _cc2_save_layers(self.host, {item["task"]: known[item["task"]] for item in recordings if item["task"] in known})

    def _video_served(self, name):
        """True when the printer hands out the exported video of this recording. A missing file
        gets no answer at all, so this waits out the timeout."""
        url = "http://%s/download?X-Token=%s&file_name=%s" % (
            self.address, urllib.parse.quote(self.token), urllib.parse.quote("video/%s.mp4" % name))
        try:
            status, body = http_request(url, headers={"Accept": "*/*"}, timeout=8)
        except FarmError:
            return False
        return status == 200 and len(body) > 0

    def delete_videos(self, items, progress=None, cancelled=None):
        """Remove each recording: its exported video, its frames, then its line in the history.
        The frames are asked for up to the print's layer count when it is known (one request for
        most prints), else up to CC2_FRAME_LIMIT.

        The names come from the printer's own history and were checked by cc2_recordings, because
        the paths reach outside the G-code folder. The printer answers "ok" whether or not it
        deleted anything, so an exported video is asked for again afterwards; when it is still
        there, the history line is kept and the recording stays listed."""
        items, done = list(items), 0
        for item in items:
            if cancelled is not None and cancelled():
                break
            name = cc2_safe_name(item.get("name"))
            if not name or not item.get("task"):
                continue
            with self._session() as session:
                if item.get("video"):
                    session.request(CC2_DELETE_FILE, {"storage_media": "local", "file_path": [CC2_VIDEO_PATH % name]}, timeout=20)
                frames = item["layers"] + CC2_FRAME_SLACK if item.get("layers") else CC2_FRAME_LIMIT
                for start in range(0, frames, CC2_FRAME_BATCH):
                    if cancelled is not None and cancelled():
                        break
                    session.request(CC2_DELETE_FILE, {"storage_media": "local", "file_path": [
                        CC2_FRAME_PATH % (name, index) for index in range(start, min(frames, start + CC2_FRAME_BATCH))]}, timeout=20)
            if cancelled is not None and cancelled():
                break
            if not (item.get("video") and self._video_served(name)):
                with self._session() as session:
                    _cc2_check(session.request(CC2_DELETE_HISTORY, {"list": [item["task"]]}, timeout=20), "Could not remove the history entry")
            done += 1
            if progress is not None:
                progress(done, len(items))
        return done

    def start_print(self, filename, options=None):
        """Start a file already on the printer. Returns which rolls it was told to print from
        ("roll 1"), or "" when none were named.

        options["filament_slots"] lists the filament numbers the G-code prints with. Each is sent to
        the roll of the same number (or the one options["toolhead_map"] names). Without that, the
        printer reuses the roll assignment of its previous print: a plate sliced with filament 1
        printed from roll 2 on two printers because their last print had used roll 2."""
        options = options or {}
        config = {
            "delay_video": bool(options.get("timelapse", False)),
            "printer_check": bool(options.get("bed_leveling", True)),
            "print_layout": options.get("plate", "A"),
        }
        params = {"filename": filename, "storage_media": "local", "config": config}
        named = ""
        with self._session() as session:
            slots = options.get("filament_slots") or []
            rolls = self._rolls(session) if slots else []
            if rolls:
                config["slot_map"] = cc2_slot_map(rolls, slots, options.get("toolhead_map"))
                numbers = [str(row["tray_id"] + 1) for row in config["slot_map"]]
                named = "roll%s %s" % ("" if len(numbers) == 1 else "s", ", ".join(numbers))
            reply = session.request(CC2_START_PRINT, params, timeout=20)
            if reply.get("error_code") == CC2_ERR_BED_MESH_MISSING:
                config["bedlevel_force"] = True
                reply = session.request(CC2_START_PRINT, params, timeout=20)
        _cc2_check(reply, "Printer refused to start the print")
        return named


_CC2_NO_ROLLS = set()
_CC2_LAYERS = {}           # {printer address: {history task id: layer count, 0 when unknown}}
CC2_MAX_LAYERS = 20000
CC2_LAYERS_FILE = "farm_send_cc2_layers.json"


def _cc2_layer_cache(host):
    """This printer's known layer counts, read once per window from the storage folder."""
    if host not in _CC2_LAYERS:
        counts = {}
        if _CC2_SHARED_DIR:
            try:
                with open(os.path.join(_CC2_SHARED_DIR, CC2_LAYERS_FILE), "r", encoding="utf-8") as handle:
                    stored = json.load(handle).get(host) or {}
                counts = {str(task): int(layers) for task, layers in stored.items()
                          if isinstance(layers, int) and 0 <= layers < CC2_MAX_LAYERS}
            except (OSError, ValueError, AttributeError):
                counts = {}
        _CC2_LAYERS[host] = counts
    return _CC2_LAYERS[host]


def _cc2_save_layers(host, counts):
    """Store a printer's layer counts next to the other printers' ones. A failed write only means
    they are read from the printer again next time."""
    _CC2_LAYERS[host] = dict(counts)
    if not _CC2_SHARED_DIR:
        return
    path = os.path.join(_CC2_SHARED_DIR, CC2_LAYERS_FILE)
    try:
        try:
            with open(path, "r", encoding="utf-8") as handle:
                everything = json.load(handle)
            if not isinstance(everything, dict):
                everything = {}
        except (OSError, ValueError):
            everything = {}
        everything[host] = counts
        write_private(path, json.dumps(everything))
    except OSError:
        pass


def cc2_safe_name(name):
    """The recording name when it is safe to put into a path on the printer, else "".

    Nothing that could point anywhere but one entry of the video or picture folder: no folder
    separators, no ".." and no control characters."""
    name = str(name or "")
    if not name or "/" in name or "\\" in name or ".." in name or name.startswith(".") or any(ord(char) < 32 for char in name):
        return ""
    return name


def cc2_recordings(tasks):
    """Time-lapses from a CC2 print history: finished prints that have frames or an exported video.

    The printer reports "picture/<name>" for frames waiting to be exported and "video/<name>.mp4"
    once exported. A print that is running or paused, or whose name is not safe, is left out."""
    out = []
    for task in tasks:
        if not isinstance(task, dict) or task.get("task_status") not in (1, 2, 3):
            continue
        state, url = task.get("time_lapse_video_status"), str(task.get("time_lapse_video_url") or "")
        if state not in (1, 2, 3) or "/" not in url:
            continue
        folder, name = url.split("/", 1)
        if folder == "video" and name.lower().endswith(".mp4"):
            name = name[:-4]
        elif folder != "picture":
            continue
        name = cc2_safe_name(name)
        if not name or not task.get("task_id"):
            continue
        out.append({"name": name, "modified": float(task.get("end_time") or task.get("begin_time") or 0),
                    "size": int(task.get("time_lapse_video_size") or 0) if state == 2 else 0,
                    "video": state == 2, "task": str(task["task_id"]), "parts": [],
                    "gcode": str(task.get("task_name") or "")})
    return out


def cc2_rolls(reply):
    """The rolls a CC2 reports in its Canvas unit: [{slot, color, type, loaded, canvas, tray}], slot from 1.

    [] when no Canvas unit is connected. The color is what was entered on the printer, from Elegoo's
    fixed list, so it can differ from the real spool."""
    for unit in ((reply or {}).get("canvas_info") or {}).get("canvas_list") or []:
        if not unit.get("connected"):
            continue
        rolls = []
        for tray in unit.get("tray_list") or []:
            if not isinstance(tray.get("tray_id"), int):
                continue
            color = str(tray.get("filament_color") or "")
            rolls.append({"slot": tray["tray_id"] + 1, "color": color if re.match(r"^#[0-9A-Fa-f]{6}$", color) else "",
                          "type": str(tray.get("filament_type") or ""), "loaded": True,
                          "canvas": unit.get("canvas_id", 0), "tray": tray["tray_id"]})
        return rolls
    return []


def cc2_slot_map(rolls, slots, mapping=None):
    """The rows that tell a CC2 which roll each G-code tool prints from: [{t, canvas_id, tray_id}].

    slots are the filament numbers the G-code uses, from 1; mapping is {filament number: roll} for
    the ones that should print from another roll. Verified on two CC2s: started with tool 0 sent to
    roll 1, both changed their active roll from 2 to 1 before the first layer."""
    have = {roll["slot"]: roll for roll in rolls}
    rows = []
    for slot in sorted({int(slot) for slot in slots}):
        try:
            roll = int((mapping or {}).get(slot, (mapping or {}).get(str(slot), slot)))
        except (TypeError, ValueError):
            roll = slot
        if roll not in have:
            raise FarmError("Not started: the plate prints with filament %d and the printer reports no roll %d." % (slot, roll))
        rows.append({"t": slot - 1, "canvas_id": have[roll]["canvas"], "tray_id": have[roll]["tray"]})
    return rows


def _cc2_check(reply, what):
    code = reply.get("error_code", 0)
    if code not in (0, None):
        reason = CC2_ERRORS.get(code) or str(reply.get("message") or "")
        raise FarmError("%s: %s" % (what, reason) if reason else "%s (printer error %s)" % (what, code))


_CC2_CLIENT_IDS = {}
_CC2_CLIENT_LOCK = threading.Lock()
_CC2_SERIAL_LOCKS = {}
_CC2_SHARED_DIR = None


def set_shared_dir(path):
    """Folder that every OrcaSlicer window of this user shares (the plugin's storage folder).

    With it set, all windows use the same client id for a printer and take turns through a lock
    file, so together they occupy one of the printer's few client slots instead of one each."""
    global _CC2_SHARED_DIR
    with _CC2_CLIENT_LOCK:
        if path != _CC2_SHARED_DIR:
            _CC2_SHARED_DIR = path
            _CC2_CLIENT_IDS.clear()


def write_private(path, text, exclusive=False):
    """Write a small file readable only by the owner, created that way in one step.

    Only calls that name the file are used. OrcaSlicer's permission check asks the user about any
    file call it cannot show a path for, which rules out os.fdopen() and os.fchmod() on a bare
    descriptor: both raised an "allow this operation with no visible target" prompt. So the file
    is created with its final permissions by os.open(), written with os.write(), and a leftover
    from an earlier run is removed first instead of having its permissions changed. O_EXCL makes
    the create fail if anything, including a planted symlink, is already at the name."""
    if not exclusive:
        try:
            os.unlink(path)
        except OSError:
            pass
    fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_NOFOLLOW", 0), 0o600)
    try:
        data = text.encode("utf-8")
        while data:
            data = data[os.write(fd, data):]
    finally:
        os.close(fd)


def _cc2_install_token(folder):
    """A random token kept in the shared folder, so two computers never pick the same client id."""
    path = os.path.join(folder, "cc2_client_token")
    for _ in range(3):   # read; or replace a damaged file, create, then read back
        try:
            with open(path, "r", encoding="ascii") as handle:
                token = handle.read().strip()
            if re.fullmatch(r"[0-9a-f]{32}", token):
                return token
        except (OSError, ValueError):
            pass
        try:
            # O_EXCL: when two windows start together, one creates the file and the other reads it.
            write_private(path, uuid.uuid4().hex, exclusive=True)
        except FileExistsError:
            try:   # present but unreadable or damaged: replace it
                if os.path.getsize(path) != 32:
                    os.unlink(path)
            except OSError:
                pass
        except OSError:
            return None
    return None


def _cc2_client_id(serial):
    """One client id per printer: shared by every window when a shared folder is set, otherwise
    for the life of this process.

    The printer keeps a registration slot per client id for about a minute after the client goes
    away and has only a few slots. A fresh id on every status poll fills them all within a minute
    and locks out ElegooSlicer and the printer's own web page; a stable id re-uses one slot."""
    with _CC2_CLIENT_LOCK:
        if serial not in _CC2_CLIENT_IDS:
            token = _cc2_install_token(_CC2_SHARED_DIR) if _CC2_SHARED_DIR else None
            tail = hashlib.sha256(("%s/%s" % (token, serial)).encode("utf-8")).hexdigest() if token else uuid.uuid4().hex
            # Same shape as the vendor web client: "0" + tag + hex, 10 characters.
            _CC2_CLIENT_IDS[serial] = ("0fs" + tail)[:10]
            _CC2_SERIAL_LOCKS.setdefault(serial, threading.Lock())
        return _CC2_CLIENT_IDS[serial]


class _FileLock:
    """Lock between processes on one computer. Released by the system if the process dies."""

    def __init__(self, path):
        self.path, self._handle = path, None

    def acquire(self, timeout):
        if fcntl is None and msvcrt is None:
            return True
        try:
            fd = os.open(self.path, os.O_RDWR | os.O_CREAT | getattr(os, "O_NOFOLLOW", 0), 0o600)
        except OSError:
            return True   # cannot lock here: carry on unshared instead of failing every request
        deadline = time.monotonic() + timeout
        while True:
            try:
                if fcntl is not None:
                    fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
                else:
                    msvcrt.locking(fd, msvcrt.LK_NBLCK, 1)
                self._handle = fd
                return True
            except OSError:
                if time.monotonic() >= deadline:
                    os.close(fd)
                    return False
                time.sleep(0.05)

    def release(self):
        fd, self._handle = self._handle, None
        if fd is None:
            return
        try:
            if fcntl is not None:
                fcntl.flock(fd, fcntl.LOCK_UN)
            else:
                os.lseek(fd, 0, os.SEEK_SET)
                msvcrt.locking(fd, msvcrt.LK_UNLCK, 1)
        except OSError:
            pass
        finally:
            os.close(fd)


def _cc2_file_lock(serial):
    if not _CC2_SHARED_DIR:
        return None
    name = "cc2_%s.lock" % hashlib.sha256(serial.encode("utf-8")).hexdigest()[:16]
    return _FileLock(os.path.join(_CC2_SHARED_DIR, name))


class _CC2Session:
    """One short-lived registered MQTT session. The printer allows only a few clients, so every
    operation connects, registers, talks and disconnects instead of holding a slot open."""

    def __init__(self, host, serial, token, timeout, port=1883):
        self.serial, self.timeout = serial, timeout
        self.client_id = _cc2_client_id(serial)
        self.mqtt = MiniMqtt(host, port, "elegoo", token, client_id=self.client_id, timeout=timeout)
        self._request_id = 0

    def __enter__(self):
        self._serial_lock = _CC2_SERIAL_LOCKS[self.serial]
        if not self._serial_lock.acquire(timeout=30):
            raise FarmError("The printer is busy answering another request")
        # Other OrcaSlicer windows use the same client id, so only one may talk at a time.
        self._file_lock = _cc2_file_lock(self.serial)
        if self._file_lock is not None and not self._file_lock.acquire(timeout=30):
            self._serial_lock.release()
            raise FarmError("The printer is busy answering another OrcaSlicer window")
        try:
            self.mqtt.connect()
        except BaseException:
            self.mqtt.close()   # the socket may be open even though the MQTT handshake failed
            self._release()
            raise
        try:
            base = "elegoo/%s" % self.serial
            self.mqtt.subscribe("%s/%s/register_response" % (base, self.client_id))
            self.mqtt.subscribe("%s/%s/api_response" % (base, self.client_id))
            self.mqtt.publish("%s/api_register" % base, {"client_id": self.client_id, "request_id": self.client_id})
            deadline = time.monotonic() + self.timeout
            while True:
                message = self.mqtt.read_message(max(0.05, deadline - time.monotonic()))
                if message is None:
                    raise FarmError("Printer did not answer the registration request")
                topic, payload = message
                if not topic.endswith("/register_response"):
                    continue
                reply = _loads(payload)
                error = str(reply.get("error", ""))
                if error in ("ok", "already registered"):
                    return self
                if error == "too many clients":
                    raise FarmError("The printer has too many connected apps. Close ElegooSlicer or another client and retry.")
                raise FarmError("Printer rejected the registration: %s" % (error or "unknown reason"))
        except BaseException:
            self.mqtt.close()
            self._release()
            raise

    def _release(self):
        try:
            if self._file_lock is not None:
                self._file_lock.release()
        finally:
            self._serial_lock.release()

    def __exit__(self, *exc):
        try:
            self.mqtt.close()
        finally:
            self._release()
        return False

    def request(self, method, params, timeout=None):
        timeout = timeout or self.timeout
        self._request_id += 1
        request_id = self._request_id
        topic = "elegoo/%s/%s/api_request" % (self.serial, self.client_id)
        self.mqtt.publish(topic, {"id": request_id, "method": method, "params": params})
        deadline = time.monotonic() + timeout
        while True:
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                raise FarmError("Printer did not answer in time")
            message = self.mqtt.read_message(remaining)
            if message is None:
                raise FarmError("Printer did not answer in time")
            if not message[0].endswith("/api_response"):
                continue
            reply = _loads(message[1])
            if reply.get("id") == request_id:
                result = reply.get("result")
                return result if isinstance(result, dict) else {}


def _loads(payload):
    try:
        value = json.loads(payload.decode("utf-8", errors="replace"))
        return value if isinstance(value, dict) else {}
    except ValueError:
        return {}


def normalize_cc2_status(info):
    machine = info.get("machine_status") or {}
    job = info.get("print_status") or {}
    code = machine.get("status", 0)
    state = CC2_STATUS.get(code, "busy")
    out = {
        "state": state,
        "state_text": CC2_STATUS_TEXT.get(code, "Busy"),
        "filename": job.get("filename") or "",
        "progress": None,
        "remaining_s": None,
        "nozzle": _temp(info.get("extruder")),
        "bed": _temp(info.get("heater_bed")),
        "errors": list(machine.get("exception_status") or []),
    }
    if state == "printing":
        progress = machine.get("progress")
        if isinstance(progress, (int, float)):
            out["progress"] = max(0.0, min(100.0, float(progress)))
        remaining = job.get("remaining_time_sec")
        if isinstance(remaining, (int, float)):
            out["remaining_s"] = int(remaining)
        sub = job.get("state") or ""
        if str(sub).lower() in ("paused", "pausing"):
            out["state"], out["state_text"] = "paused", "Paused"
    # An idle printer keeps showing 100% after a print that ran to the end, and 0 before any print.
    progress = machine.get("progress")
    out["last_result"] = "complete" if state == "idle" and isinstance(progress, (int, float)) and progress >= 100 else ""
    if out["errors"] and state == "idle":
        out["state_text"] = "Idle (warning %s)" % ", ".join(str(e) for e in out["errors"])
    return out


WATCHED_STATES = ("idle", "printing", "paused", "error")


def status_event(before, now, name):
    """What changed on a printer between two status reads that is worth telling the user.

    before: the last status seen in a watched state, or None on the first read. Returns
    (level, text) or None. "Offline" and "busy" reads are skipped by the caller, so a print that
    ends while the network blips is still reported from the last "printing" read."""
    if not before or now.get("state") not in WATCHED_STATES:
        return None
    was, state = before.get("state"), now.get("state")
    job = before.get("filename") or now.get("filename") or "its print"
    if state == "error" and was != "error":
        return "error", "%s stopped with an error: %s" % (name, now.get("state_text") or "Error")
    if state == "paused" and was == "printing":
        return "error", "%s paused %s" % (name, job)
    if state == "idle" and was in ("printing", "paused"):
        result = now.get("last_result") or ""
        progress = before.get("progress")
        if result == "cancelled":
            return "info", "%s: %s was cancelled" % (name, job)
        if result == "complete" or (isinstance(progress, (int, float)) and progress >= 99):
            return "info", "%s finished %s" % (name, job)
        # No result reported (Centauri Carbon 2) and not near the end: do not claim it finished.
        return "info", "%s stopped printing %s at %d%%" % (name, job, progress or 0)
    if state in ("printing", "paused"):
        fresh = [code for code in now.get("errors") or [] if code not in (before.get("errors") or [])]
        if fresh:
            return "error", "%s reports a problem while printing (code %s)" % (name, ", ".join(str(code) for code in fresh))
    return None


def _temp(block):
    if not isinstance(block, dict):
        return None
    value = block.get("temperature")
    if not isinstance(value, (int, float)):
        return None
    target = block.get("target")
    return {"current": round(float(value), 1), "target": round(float(target), 1) if isinstance(target, (int, float)) else 0.0}


# --------------------------------------------------------------------------------------
# Moonraker (Snapmaker U1 and other Klipper printers)
# --------------------------------------------------------------------------------------

class Moonraker:
    kind = KIND_MOONRAKER

    def __init__(self, address, api_key="", timeout=6):
        self.address = host_of(address)
        self.api_key = api_key or ""
        self.timeout = timeout

    def _headers(self, extra=None):
        headers = dict(extra or {})
        if self.api_key:
            headers["X-Api-Key"] = self.api_key
        return headers

    def _get(self, path, timeout=None):
        return http_json("http://%s%s" % (self.address, path), headers=self._headers(), timeout=timeout or self.timeout)

    def _post(self, path, timeout=None):
        return http_json("http://%s%s" % (self.address, path), method="POST", data=b"", headers=self._headers(),
                         timeout=timeout or self.timeout)

    def identify(self):
        info = (self._get("/printer/info").get("result") or {})
        model = ""
        try:
            objects = self._get("/printer/objects/query?configfile=settings").get("result", {})
            settings = objects.get("status", {}).get("configfile", {}).get("settings", {})
            if any(key.startswith("extruder") for key in settings) and "extruder3" in settings:
                model = "Snapmaker U1"
        except FarmError:
            pass
        try:
            machine = self._get("/machine/system_info").get("result", {}).get("system_info", {})
            product = (machine.get("product_info") or {}).get("machine_type") or ""
            if product:
                model = product
        except FarmError:
            pass
        return {"model": model, "name": info.get("hostname", ""), "serial": "", "firmware": info.get("software_version", "")}

    def status(self):
        reply = self._get("/printer/objects/query?print_stats&virtual_sdcard&heater_bed&display_status&toolhead&extruder"
                          "&extruder1&extruder2&extruder3&print_task_config")
        status = reply.get("result", {}).get("status", {})
        filename = (status.get("print_stats") or {}).get("filename") or ""
        active = (status.get("print_stats") or {}).get("state") in ("printing", "paused")
        return normalize_moonraker_status(status, self._klippy_state, self._estimated_time(filename) if active else None)

    def _estimated_time(self, filename):
        """The slicer's time estimate for a file, asked once per file and remembered."""
        if not filename:
            return None
        key = (self.address, filename)
        if key not in _MOONRAKER_ESTIMATES:
            try:
                reply = self._get("/server/files/metadata?filename=%s" % urllib.parse.quote(filename))
                value = (reply.get("result") or {}).get("estimated_time")
            except FarmError:
                return None   # not remembered: ask again on the next poll
            if len(_MOONRAKER_ESTIMATES) > 64:
                _MOONRAKER_ESTIMATES.clear()
            _MOONRAKER_ESTIMATES[key] = float(value) if isinstance(value, (int, float)) and value > 0 else None
        return _MOONRAKER_ESTIMATES[key]

    def _klippy_state(self):
        return (self._get("/printer/info").get("result") or {})

    def list_files(self, limit=None):
        reply = self._get("/server/files/list?root=gcodes", timeout=15)
        return [entry.get("path", "") for entry in reply.get("result") or []]

    def list_stored(self):
        """Every stored G-code file as {name, modified, size}."""
        reply = self._get("/server/files/list?root=gcodes", timeout=20)
        return [{"name": str(entry.get("path") or ""), "modified": float(entry.get("modified") or 0), "size": int(entry.get("size") or 0)}
                for entry in reply.get("result") or []
                if isinstance(entry, dict) and str(entry.get("path") or "").lower().endswith((".gcode", ".g", ".gco"))]

    def delete_files(self, names, progress=None, cancelled=None):
        names, done = list(names), 0
        for name in names:
            if cancelled is not None and cancelled():
                break
            self.delete_file(name)
            done += 1
            if progress is not None:
                progress(done, len(names))
        return done

    def delete_file(self, filename):
        http_json("http://%s/server/files/gcodes/%s" % (self.address, urllib.parse.quote(filename)), method="DELETE",
                  headers=self._headers(), timeout=self.timeout)

    def list_videos(self):
        """The time-lapse recordings a Snapmaker keeps, one entry per recording (see video_sets).
        None when the printer has no camera folder to list."""
        try:
            reply = self._get("/server/files/list?root=camera", timeout=20)
        except FarmError:
            return None
        return video_sets(reply.get("result") or [])

    def delete_videos(self, items, progress=None, cancelled=None):
        """Remove each recording with its pictures. Returns how many recordings were worked through.

        On a Snapmaker U1 the camera folder is read-only to the file API (HTTP 405), so a recording
        is removed through Snapmaker's camera service by the 14-digit time its name ends with, as
        Snapmaker's own app does. Verified on a U1 on 2026-11-21: its video, picture and cover went.
        Other printers, and pictures with no such time, are removed file by file."""
        items, done = list(items), 0
        service = True
        for item in items:
            if cancelled is not None and cancelled():
                break
            stamp = re.search(r"_(\d{14})$", os.path.basename(str(item.get("name") or "")))
            if stamp and service:
                try:
                    websocket_rpc(self.address, "camera.delete_timelapse_instance", {"date_index": stamp.group(1)}, timeout=30)
                    stamp = "done"
                except RpcError as error:
                    if error.code != -32601:
                        raise FarmError("Could not remove the recording: %s" % error)
                    service = False     # not a Snapmaker: fall back to the file API
            if stamp != "done":
                for part in item.get("parts") or []:
                    http_json("http://%s/server/files/camera/%s" % (self.address, urllib.parse.quote(part)), method="DELETE",
                              headers=self._headers(), timeout=self.timeout)
            done += 1
            if progress is not None:
                progress(done, len(items))
        return done

    def upload(self, path, filename, progress=None, cancelled=None):
        size = os.path.getsize(path)
        if size <= 0:
            raise FarmError("The G-code file is empty")
        boundary = "----farmsend" + uuid.uuid4().hex
        head = ("--%s\r\nContent-Disposition: form-data; name=\"root\"\r\n\r\ngcodes\r\n"
                "--%s\r\nContent-Disposition: form-data; name=\"print\"\r\n\r\nfalse\r\n"
                "--%s\r\nContent-Disposition: form-data; name=\"file\"; filename=\"%s\"\r\n"
                "Content-Type: application/octet-stream\r\n\r\n" % (boundary, boundary, boundary, filename.replace('"', "_"))
                ).encode("utf-8")
        tail = ("\r\n--%s--\r\n" % boundary).encode("utf-8")
        total = len(head) + size + len(tail)
        host, _, port = self.address.partition(":")
        connection = http.client.HTTPConnection(host, int(port or 80), timeout=60)
        try:
            connection.putrequest("POST", "/server/files/upload")
            connection.putheader("Content-Type", "multipart/form-data; boundary=%s" % boundary)
            connection.putheader("Content-Length", str(total))
            if self.api_key:
                connection.putheader("X-Api-Key", self.api_key)
            connection.endheaders()
            connection.send(head)
            sent = 0
            with open(path, "rb") as handle:
                while True:
                    if cancelled is not None and cancelled():
                        raise FarmError("Upload cancelled")
                    chunk = handle.read(256 * 1024)
                    if not chunk:
                        break
                    connection.send(chunk)
                    sent += len(chunk)
                    if progress is not None:
                        progress(sent, size)
            if sent != size:
                raise FarmError("The G-code file changed while uploading")
            connection.send(tail)
            connection.sock.settimeout(180)
            response = connection.getresponse()
            body = response.read()
        except (FarmError, PermissionError):
            raise
        except ConnectionRefusedError:
            raise FarmError("Cannot reach printer: connection refused")
        except (socket.timeout, TimeoutError):
            raise FarmError("Upload failed: the printer stopped responding")
        except (OSError, http.client.HTTPException) as error:
            raise FarmError("Upload failed: %s" % (getattr(error, "strerror", None) or error))
        finally:
            connection.close()
        if response.status in (401, 403):
            raise FarmError("Access denied (HTTP %d). Check the API key." % response.status)
        if response.status >= 300:
            raise FarmError("Upload failed: HTTP %d %s" % (response.status, body[:200].decode("utf-8", errors="replace")))
        try:
            item = json.loads(body.decode("utf-8", errors="replace")).get("result", {}).get("item", {})
            return item.get("path") or filename
        except ValueError:
            return filename

    def start_print(self, filename, options=None):
        """Start a file already on the printer.

        Snapmaker firmware decides bed leveling, flow calibration and time-lapse from options that
        travel WITH the start request (server.files.start_local_print, websocket only). A plain
        Moonraker start carries none, and the printer then silently skips auto bed leveling. So the
        Snapmaker call is tried first; a printer that does not know it gets the standard start."""
        options = options or {}
        table = toolhead_map_table(options.get("toolhead_map"))
        remapped = any(slot != tool for slot, tool in table)
        params = {"type": "gcode", "path": filename, "options": {
            "map_table": table,
            "bed_level": 1 if options.get("bed_leveling", True) else 0,
            "flow_calibrate": 1 if options.get("flow_calibrate", False) else 0,
            "time_lapse_camera": 1 if options.get("timelapse", False) else 0,
        }}
        try:
            result = websocket_rpc(self.address, "server.files.start_local_print", params, timeout=30)
        except RpcError as error:
            text = str(error).lower()
            if error.code == -32601 or "not found" in text or "unknown method" in text:
                if remapped:
                    # A plain start cannot carry the mapping: it would print from the sliced toolhead.
                    raise FarmError("Not started: this printer cannot print from a different toolhead than the file was sliced for.")
                self._post("/printer/print/start?filename=%s" % urllib.parse.quote(filename), timeout=30)
                return "standard"
            raise FarmError("Printer refused to start the print: %s" % error)
        if isinstance(result, dict) and str(result.get("state", "")).lower() not in ("success", "ok", ""):
            raise FarmError("Printer refused to start the print: %s" % (result.get("message") or result.get("state")))
        return "snapmaker"

    def cancel_print(self):
        self._post("/printer/print/cancel", timeout=30)

    def keep_parts(self, keep, cancelled=None, wait=None):
        """Right after a start: print only the first `keep` labelled parts of the plate and skip the rest.

        The printer lists the plate's parts a moment after the file starts. The skip commands then
        wait in the printer's queue until its first heat-up pause ends, and take effect before
        anything is extruded (seen on a U1: 26 of 28 skipped, 0 mm used). Returns (kept, total).
        Raises FarmError when the skips cannot be confirmed; the caller must then stop the print."""
        wait = KEEP_PARTS_WAIT if wait is None else wait
        deadline = time.monotonic() + wait
        query = "/printer/objects/query?exclude_object&print_stats=state"
        names = []
        while not names:
            if cancelled is not None and cancelled():
                raise FarmError("cancelled")
            status = (self._get(query).get("result") or {}).get("status") or {}
            names = [str(o.get("name")) for o in (status.get("exclude_object") or {}).get("objects") or [] if o.get("name")]
            if names:
                break
            if (status.get("print_stats") or {}).get("state") not in ("printing", "paused") and time.monotonic() > deadline - wait + 20:
                raise FarmError("the printer is not printing")
            if time.monotonic() > deadline:
                raise FarmError("the printer did not list the parts on this plate")
            time.sleep(KEEP_PARTS_POLL)
        total = len(names)
        if not 1 <= keep <= total:
            raise FarmError("the plate has %d parts" % total)
        skip = names[keep:]
        for start in range(0, len(skip), 20):          # a few at a time keeps each request short
            script = "\n".join("EXCLUDE_OBJECT NAME=%s" % name for name in skip[start:start + 20])
            self._post("/printer/gcode/script?script=%s" % urllib.parse.quote(script), timeout=max(30, deadline - time.monotonic()))
        for _ in range(20):                            # the printer's own list is the proof
            status = (self._get(query).get("result") or {}).get("status") or {}
            if len((status.get("exclude_object") or {}).get("excluded_objects") or []) == len(skip):
                return keep, total
            time.sleep(KEEP_PARTS_POLL)
        raise FarmError("the printer did not confirm the skipped parts")


_MOONRAKER_ESTIMATES = {}


def count_objects(path):
    """How many separately labelled parts the G-code defines (Klipper EXCLUDE_OBJECT_DEFINE lines).
    0 when the slicer did not label objects, as on a Centauri Carbon 2."""
    found = 0
    with open(path, "rb") as handle:
        for line in handle:
            if line.startswith(b"EXCLUDE_OBJECT_DEFINE"):
                found += 1
    return found


def moonraker_remaining(progress, elapsed, estimated_time=None):
    """Seconds left. progress is 0..1 of the file, elapsed is Klipper's print_duration.

    With the slicer's estimate: the unprinted share of it. Without: extrapolate from elapsed
    time, but only once enough has printed, because print_duration also counts heating and bed
    leveling and that swamps the early figure (29 hours shown for a 5 hour job at 1%)."""
    if estimated_time:
        return int(estimated_time * (1.0 - progress))
    if isinstance(elapsed, (int, float)) and progress >= 0.10:
        return int(elapsed / progress - elapsed)
    return None


def normalize_moonraker_status(status, klippy_info=None, estimated_time=None):
    stats = status.get("print_stats") or {}
    sdcard = status.get("virtual_sdcard") or {}
    raw_state = str(stats.get("state") or "").lower()
    mapping = {"standby": ("idle", "Idle"), "complete": ("idle", "Idle (last print complete)"),
               "cancelled": ("idle", "Idle (last print cancelled)"), "printing": ("printing", "Printing"),
               "paused": ("paused", "Paused"), "error": ("error", "Error")}
    state, text = mapping.get(raw_state, ("busy", raw_state.capitalize() or "Unknown"))
    result = raw_state if raw_state in ("complete", "cancelled") else ""
    if not raw_state and klippy_info is not None:
        info = klippy_info()
        if info.get("state") != "ready":
            state, text = "error", "Klipper: %s" % (info.get("state_message") or info.get("state") or "not ready").splitlines()[0]
    if state == "error" and stats.get("message"):
        text = "Error: %s" % str(stats["message"]).splitlines()[0]
    out = {"state": state, "state_text": text, "filename": stats.get("filename") or "", "progress": None,
           "remaining_s": None, "nozzle": None, "bed": _temp(status.get("heater_bed")), "errors": [],
           "last_result": result}
    if isinstance(stats.get("filament_used"), (int, float)):
        out["extruded_mm"] = float(stats["filament_used"])      # 0 while a print is still heating
    # Report the hottest tool: on a tool changer the parked tools sit near ambient.
    tools = [_temp(status.get(name)) for name in ("extruder", "extruder1", "extruder2", "extruder3")]
    tools = [tool for tool in tools if tool]
    if tools:
        out["nozzle"] = max(tools, key=lambda tool: (tool["target"], tool["current"]))
    out["tools"] = _moonraker_tools(status.get("print_task_config"))
    out["has_print_options"] = isinstance(status.get("print_task_config"), dict)
    if state in ("printing", "paused"):
        progress = sdcard.get("progress")
        if isinstance(progress, (int, float)):
            out["progress"] = max(0.0, min(100.0, float(progress) * 100.0))
            progress = max(0.0, min(1.0, float(progress)))
            out["remaining_s"] = moonraker_remaining(progress, stats.get("print_duration"), estimated_time)
    return out


def _moonraker_tools(config):
    """What a Snapmaker reports as loaded in each toolhead: [{slot, color, type, loaded}]."""
    if not isinstance(config, dict):
        return []
    colors = config.get("filament_color_rgba") or []
    types = config.get("filament_type") or []
    exists = config.get("filament_exist") or []
    tools = []
    for index in range(max(len(colors), len(types))):
        raw = str(colors[index]) if index < len(colors) else ""
        tools.append({"slot": index + 1,
                      "color": ("#" + raw[:6]) if re.match(r"^[0-9A-Fa-f]{6}", raw) else "",
                      "type": str(types[index]) if index < len(types) else "",
                      "loaded": bool(exists[index]) if index < len(exists) else True})
    return tools


# --------------------------------------------------------------------------------------
# Printer registry
# --------------------------------------------------------------------------------------

def make_client(printer, timeout=6):
    kind = printer.get("kind")
    if kind == KIND_CC2:
        return ElegooCC2(printer.get("address", ""), printer.get("access_code", ""), timeout=timeout,
                         mqtt_port=printer.get("mqtt_port") or 1883)
    if kind == KIND_MOONRAKER:
        return Moonraker(printer.get("address", ""), printer.get("api_key", ""), timeout=timeout)
    raise FarmError("Unknown printer type: %s" % kind)


def validate_printer(printer):
    name = (printer.get("name") or "").strip()
    address = host_of(printer.get("address"))
    if not name:
        raise FarmError("Give the printer a name")
    if printer.get("kind") not in KINDS:
        raise FarmError("Choose a printer type")
    if not re.match(r"^[A-Za-z0-9._\-]+(:\d{1,5})?$", address):
        raise FarmError("Enter the printer's IP address or host name")
    if not (printer.get("model") or "").strip():
        raise FarmError("Enter the printer model, exactly as the printer preset names it")
    return {
        "id": printer.get("id") or uuid.uuid4().hex[:12],
        "name": name[:60],
        "kind": printer["kind"],
        "address": address,
        "model": printer["model"].strip()[:80],
        "access_code": (printer.get("access_code") or "").strip(),
        "api_key": (printer.get("api_key") or "").strip(),
        "mqtt_port": int(printer.get("mqtt_port") or 0),
        "nozzle": first_number(printer.get("nozzle")),   # mm, from the printer preset; None when unknown
    }


def toolhead_map_table(mapping, count=4):
    """Snapmaker map_table rows [slicer slot index, physical toolhead index], both from 0.

    mapping is {slicer slot: toolhead}, both counted from 1 as the panel shows them; slots not
    named print from their own toolhead. Verified on a U1: the printer reports the table back in
    print_task_config.extruder_map_table and heats the mapped toolhead."""
    table = [[index, index] for index in range(count)]
    for slot, tool in (mapping or {}).items():
        try:
            slot, tool = int(slot), int(tool)
        except (TypeError, ValueError):
            continue
        if 1 <= slot <= count and 1 <= tool <= count:
            table[slot - 1] = [slot - 1, tool - 1]
    return table


COLOR_GAP = 90     # summed RGB difference above which two colors count as different (black vs dark gray passes)


def color_gap(a, b):
    """How far apart two #RRGGBB colors are, 0 when either is missing or unreadable."""
    values = []
    for color in (a, b):
        if not isinstance(color, str) or not re.match(r"^#[0-9a-fA-F]{6}", color):
            return 0
        values.append([int(color[i:i + 2], 16) for i in (1, 3, 5)])
    return sum(abs(x - y) for x, y in zip(*values))


def toolhead_color_problem(tools, tool, color):
    """Why this toolhead would print the wrong color, judged from what the printer reports, or ""."""
    match = [entry for entry in tools or [] if entry.get("slot") == tool]
    if match and match[0].get("loaded") and color_gap(match[0].get("color"), color) > COLOR_GAP:
        return "toolhead %s holds a different color than the plate was sliced with" % tool
    return ""


def toolhead_problem(tools, tool, material):
    """Why a plate cannot print from this toolhead, judged from what the printer reports, or "".

    tools: the printer's toolhead report [{slot, color, type, loaded}]; empty when the printer
    reports none, in which case nothing can be checked."""
    if not tools:
        return ""
    match = [entry for entry in tools if entry.get("slot") == tool]
    if not match:
        return "the printer has no toolhead %s" % tool
    if not match[0].get("loaded"):
        return "toolhead %s reports no filament" % tool
    loaded = str(match[0].get("type") or "").strip().upper()
    wanted = str(material or "").strip().upper()
    if loaded and wanted and loaded != wanted:
        return "toolhead %s holds %s and the plate was sliced for %s" % (tool, loaded, wanted)
    return ""


def first_number(value):
    """0.4 from 0.4, "0.4", "0.4,0.4,0.4,0.4", ["0.4", "0.4"] or "0.4;0.4". None when there is none."""
    if isinstance(value, (list, tuple)):
        value = value[0] if value else None
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        return float(value) if value > 0 else None
    match = re.match(r"\s*(\d+(?:\.\d+)?)", str(value or ""))
    return float(match.group(1)) if match and float(match.group(1)) > 0 else None


def nozzle_mismatch(plate_nozzle, printer_nozzle):
    """Text describing a nozzle-size mismatch, or "" when they agree or either side is unknown."""
    plate, printer = first_number(plate_nozzle), first_number(printer_nozzle)
    if plate is None or printer is None or abs(plate - printer) < 0.01:
        return ""
    return "this plate was sliced for a %g mm nozzle and the printer is set up with %g mm" % (plate, printer)


AUTO_OPEN_MARK = "farm_send_opening"


def auto_open_begin(folder):
    """Leave a mark before the panel is opened by itself. False when the mark of an earlier attempt
    is still there: that attempt never finished, so OrcaSlicer most likely went down while opening
    the panel at start, and it must not be tried again."""
    path = os.path.join(folder, AUTO_OPEN_MARK)
    if os.path.exists(path):
        return False
    write_private(path, "1")
    return True


def auto_open_done(folder):
    try:
        os.remove(os.path.join(folder, AUTO_OPEN_MARK))
    except OSError:
        pass


class PrinterStore:
    """Printers saved as JSON in the plugin's storage folder. The file holds LAN access codes,
    so it is written with owner-only permissions."""

    def __init__(self, path):
        self.path = path
        self._lock = threading.Lock()
        self.printers = []
        self.combos = {}
        self.cleanup = dict(DEFAULT_CLEANUP)
        self.video_cleanup = dict(DEFAULT_CLEANUP)
        self.auto_open = True
        self._stamp = None
        self.load()

    def sync(self):
        """Pick up what another OrcaSlicer window saved. Called before every change, so a change made
        here is applied on top of the other window's and neither is lost. True when it reloaded."""
        if file_stamp(self.path) == self._stamp:
            return False
        self.load()
        return True

    def set_cleanup(self, rule):
        self.sync()
        self.cleanup = clean_rule(rule)
        self.save()

    def set_video_cleanup(self, rule):
        """The rule for time-lapse recordings. Recordings are only ever removed by hand."""
        self.sync()
        self.video_cleanup = dict(clean_rule(rule), auto=False)
        self.save()

    def set_auto_open(self, value):
        self.sync()
        self.auto_open = bool(value)
        self.save()

    def load(self):
        self.combos = {}
        self.cleanup = dict(DEFAULT_CLEANUP)
        self.video_cleanup = dict(DEFAULT_CLEANUP)
        self.auto_open = True
        self._stamp = file_stamp(self.path)
        try:
            with open(self.path, "r", encoding="utf-8") as handle:
                data = json.load(handle)
            self.printers = [p for p in data.get("printers", []) if isinstance(p, dict) and p.get("id")]
            combos = data.get("combos", {})
            if isinstance(combos, dict):
                self.combos = {key: value for key, value in combos.items() if isinstance(value, dict) and value.get("printer")}
            self.cleanup = clean_rule(data.get("cleanup"))
            self.video_cleanup = dict(clean_rule(data.get("video_cleanup")), auto=False)
            self.auto_open = data.get("auto_open") is not False
        except (OSError, ValueError, AttributeError):
            self.printers = []

    def save(self):
        with self._lock:
            temp = self.path + ".tmp"
            # Created owner-only in one step: the file holds access codes, so it must never exist
            # with wider permissions, and O_NOFOLLOW refuses a symlink planted at the temp name.
            write_private(temp, json.dumps({"version": 1, "printers": self.printers, "combos": self.combos,
                                            "cleanup": self.cleanup, "video_cleanup": self.video_cleanup,
                                            "auto_open": self.auto_open}, indent=2))
            os.replace(temp, self.path)
            self._stamp = file_stamp(self.path)

    def get(self, printer_id):
        for printer in self.printers:
            if printer["id"] == printer_id:
                return printer
        return None

    def upsert(self, printer):
        printer = validate_printer(printer)
        self.sync()
        for index, existing in enumerate(self.printers):
            if existing["id"] == printer["id"]:
                self.printers[index] = printer
                break
        else:
            self.printers.append(printer)
        self.save()
        return printer

    def remove(self, printer_id):
        self.sync()
        self.printers = [p for p in self.printers if p["id"] != printer_id]
        self.save()

    def set_combo(self, model, printer, process, filaments):
        """Remember which presets to slice with for one printer type."""
        key = model_key(model)
        if not key or not printer:
            raise FarmError("Select a printer preset in OrcaSlicer first")
        self.sync()
        self.combos[key] = {"label": model.strip(), "printer": printer, "process": process or "",
                            "filaments": [name for name in (filaments or []) if name]}
        self.save()
        return key

    def remove_combo(self, key):
        self.sync()
        if self.combos.pop(key, None) is not None:
            self.save()

    def hosts(self):
        return sorted({host_of(p.get("address", "")).split(":")[0] for p in self.printers if p.get("address")})


# --------------------------------------------------------------------------------------
# Cleaning old G-code off the printers
# --------------------------------------------------------------------------------------

DEFAULT_CLEANUP = {"mode": "age", "days": 30, "keep": 50, "auto": False}


def clean_rule(rule):
    """A cleanup rule with every field present and within sane limits."""
    rule = rule if isinstance(rule, dict) else {}
    out = dict(DEFAULT_CLEANUP)
    if rule.get("mode") in ("age", "count"):
        out["mode"] = rule["mode"]
    for key, low, high in (("days", 1, 3650), ("keep", 1, 5000)):
        try:
            out[key] = max(low, min(high, int(rule.get(key, out[key]))))
        except (TypeError, ValueError):
            pass
    out["auto"] = bool(rule.get("auto", False))
    return out


def rule_text(rule):
    rule = clean_rule(rule)
    if rule["mode"] == "count":
        return "keep the newest %d files" % rule["keep"]
    return "keep files newer than %d day%s" % (rule["days"], "" if rule["days"] == 1 else "s")


def files_to_clean(files, rule, protect=(), now=None):
    """The stored files a rule removes, oldest first.

    Never chosen: a protected name (the file being printed), and in age mode a file with no
    date, because "unknown age" is not "old"."""
    rule = clean_rule(rule)
    now = time.time() if now is None else now
    protected = {os.path.basename(str(name)) for name in protect if name}
    newest_first = sorted(files, key=lambda item: item.get("modified") or 0, reverse=True)
    if rule["mode"] == "count":
        chosen = newest_first[rule["keep"]:]
    else:
        limit = now - rule["days"] * 86400
        chosen = [item for item in newest_first if 0 < (item.get("modified") or 0) < limit]
    chosen = [item for item in chosen if os.path.basename(item["name"]) not in protected]
    return sorted(chosen, key=lambda item: item.get("modified") or 0)


VIDEO_TYPES = (".mp4", ".jpg", ".jpeg", ".png")
VIDEO_LIVE = ("monitor",)      # the camera's live picture: never a recording


def video_sets(entries):
    """Group a camera folder listing into recordings: [{name, modified, size, parts, video}].

    A Snapmaker U1 writes each time-lapse as <print>_<time>.mp4 with <print>_<time>.jpg and
    <print>_<time>_cover.jpg next to it; they are kept or removed together. Pictures whose video
    is already gone form a recording of their own. The live camera picture is left out."""
    sets = {}
    for entry in entries:
        if not isinstance(entry, dict):
            continue
        path = str(entry.get("path") or "")
        base, kind = os.path.splitext(path)
        if kind.lower() not in VIDEO_TYPES:
            continue
        stem = base[:-len("_cover")] if base.endswith("_cover") else base
        if os.path.basename(stem).lower() in VIDEO_LIVE:
            continue
        item = sets.setdefault(stem, {"name": stem, "modified": 0.0, "size": 0, "parts": [], "video": False})
        item["parts"].append(path)
        item["size"] += int(entry.get("size") or 0)
        item["modified"] = max(item["modified"], float(entry.get("modified") or 0))
        item["video"] = item["video"] or kind.lower() == ".mp4"
    return list(sets.values())


def videos_to_clean(items, rule, running="", now=None):
    """The recordings a rule removes, oldest first. The recording of the print that is running
    (its name starts with the name of the file being printed) is never chosen."""
    stem = os.path.splitext(os.path.basename(str(running or "")))[0]
    if stem:
        items = [item for item in items if not os.path.basename(item["name"]).startswith(stem)]
    return files_to_clean(items, rule, (), now)


def storage_summary(files):
    dated = [item["modified"] for item in files if item.get("modified")]
    return {"count": len(files), "bytes": sum(item.get("size") or 0 for item in files), "oldest": min(dated) if dated else None}


def file_stamp(path):
    """Changes whenever the file is rewritten; None when it does not exist."""
    try:
        info = os.stat(path)
        return (info.st_mtime_ns, info.st_size)
    except OSError:
        return None


def plan_order(remaining, printers, entries):
    """What to start on which free printer to work off `remaining` parts, spread evenly.

    printers: free printers in the order to fill them. entries: the kept plates of the item.
    A printer that can skip parts (not a Centauri Carbon 2, plate labelled part by part) prints
    exactly its share, so ten parts over five such printers is two each. A printer that can only
    print whole plates gets the kept plate nearest its share, and is left out when that plate would
    be more than double the share. With no part-skipping printer at all, whole plates are handed
    out one printer after another until the order is covered (a few extras possible).
    Each pick: printer_id, entry_id, parts (to print there), plate (parts on that kept plate)."""
    def fitting(printer):
        return [e for e in entries if model_matches(e.get("printer_model"), printer.get("model"))
                and not nozzle_mismatch(e.get("nozzle_diameter"), printer.get("nozzle")) and (e.get("parts") or 0) > 0]

    def countable(printer):
        if printer.get("kind") == KIND_CC2:
            return []
        return [e for e in fitting(printer) if e.get("objects") == e.get("parts") and e["parts"] > 1]

    usable = [p for p in printers if fitting(p)]
    flexible = [p for p in usable if countable(p)]
    plan = []
    if remaining <= 0 or not usable:
        return plan
    if not flexible:
        for printer in usable:
            if remaining <= 0:
                break
            fits = fitting(printer)
            under = [e for e in fits if e["parts"] <= remaining]
            pick = max(under, key=lambda e: e["parts"]) if under else min(fits, key=lambda e: e["parts"])
            plan.append({"printer_id": printer["id"], "entry_id": pick["id"], "parts": pick["parts"], "plate": pick["parts"]})
            remaining -= pick["parts"]
        return plan
    share = -(-remaining // len(usable))
    for printer in usable:
        if printer in flexible or remaining <= 0:
            continue
        fits = fitting(printer)
        over = [e for e in fits if share <= e["parts"] <= 2 * share]
        under = [e for e in fits if e["parts"] < share]
        pick = min(over, key=lambda e: e["parts"]) if over else (max(under, key=lambda e: e["parts"]) if under else None)
        if pick is not None:
            plan.append({"printer_id": printer["id"], "entry_id": pick["id"], "parts": pick["parts"], "plate": pick["parts"]})
            remaining -= pick["parts"]
    while remaining > 0 and flexible:
        base, extra = divmod(remaining, len(flexible))
        for index, printer in enumerate(list(flexible)):
            want = base + (1 if index < extra else 0)
            plates = countable(printer)
            pick = min([e for e in plates if e["parts"] >= want] or [max(plates, key=lambda e: e["parts"])], key=lambda e: e["parts"])
            count = min(want, pick["parts"])
            if count > 0:
                plan.append({"printer_id": printer["id"], "entry_id": pick["id"], "parts": count, "plate": pick["parts"]})
                remaining -= count
        break       # one plate per printer: whatever is still left waits for the next round
    order = {p["id"]: n for n, p in enumerate(printers)}
    return sorted(plan, key=lambda pick: order[pick["printer_id"]])


class OrderBook:
    """Orders being worked off, kept in a file so an unfinished order survives a restart.

    An order: item, quantity wanted, optional toolhead and note, and the plates started for it.
    A plate is "printing" from its start until the user clears that bed and says how many parts
    were good; only then does it count toward the order."""

    def __init__(self, path):
        self.path, self._lock, self._stamp = path, threading.Lock(), None
        self.load()

    def sync(self):
        """As PrinterStore.sync: reload when another window rewrote the file."""
        if file_stamp(self.path) == self._stamp:
            return False
        self.load()
        return True

    def load(self):
        self.orders, self.toolhead_names = [], ["", "", "", ""]
        self._stamp = file_stamp(self.path)
        try:
            with open(self.path, "r", encoding="utf-8") as handle:
                data = json.load(handle)
            self.orders = [o for o in data.get("orders", []) if isinstance(o, dict) and o.get("id")]
            names = data.get("toolhead_names")
            if isinstance(names, list):
                self.toolhead_names = ([str(n)[:20] for n in names] + [""] * 4)[:4]
        except (OSError, ValueError, AttributeError):
            pass

    def save(self):
        with self._lock:
            write_private(self.path + ".tmp", json.dumps({"version": 1, "orders": self.orders,
                                                         "toolhead_names": self.toolhead_names}, indent=1))
            os.replace(self.path + ".tmp", self.path)
            self._stamp = file_stamp(self.path)

    def get(self, order_id):
        return next((o for o in self.orders if o["id"] == order_id), None)

    def add(self, item, quantity, toolhead=None, note=""):
        self.sync()
        order = {"id": uuid.uuid4().hex[:10], "item": item, "quantity": quantity, "toolhead": toolhead,
                 "note": note, "created": time.time(), "plates": []}
        self.orders.append(order)
        self.save()
        return order

    def delete(self, order_id):
        self.sync()
        self.orders = [o for o in self.orders if o["id"] != order_id]
        self.save()

    def open_plate(self, printer_id):
        """(order, plate) still on this printer and not yet counted, or (None, None)."""
        for order in self.orders:
            for plate in order["plates"]:
                if plate.get("printer_id") == printer_id and plate.get("state") == "printing":
                    return order, plate
        return None, None

    def add_plate(self, order_id, printer_id, printer_name, parts, filename):
        self.sync()
        _, earlier = self.open_plate(printer_id)
        if earlier is not None:            # the bed was reused without a count: it yields nothing
            earlier.update(state="counted", good=0)
        order = self.get(order_id)
        if order is not None:
            order["plates"].append({"printer_id": printer_id, "printer_name": printer_name, "parts": parts,
                                    "filename": filename, "sent_at": time.time(), "state": "printing", "good": None})
        self.save()

    def count(self, printer_id, good):
        self.sync()
        order, plate = self.open_plate(printer_id)
        if plate is None:
            return None
        plate.update(state="counted", good=max(0, min(int(good), 99999)))
        self.save()
        return order

    @staticmethod
    def totals(order):
        good = sum(p.get("good") or 0 for p in order["plates"] if p.get("state") == "counted")
        printing = sum(p.get("parts") or 0 for p in order["plates"] if p.get("state") == "printing")
        return good, printing, max(0, order["quantity"] - good - printing)


RUN_LOG_LIMIT = 2000


def run_result(before, now):
    """How a print ended, read from two status reads, or None while nothing ended.
    finished, cancelled, error, or stopped (ended early with no reason reported)."""
    if not before or now.get("state") not in WATCHED_STATES:
        return None
    was, state = before.get("state"), now.get("state")
    if state == "error" and was in ("printing", "paused"):
        return "error"
    if state == "idle" and was in ("printing", "paused"):
        if (now.get("last_result") or "") == "cancelled":
            return "cancelled"
        progress = before.get("progress")
        if now.get("last_result") == "complete" or (isinstance(progress, (int, float)) and progress >= 99):
            return "finished"
        return "stopped"
    return None


class RunLog:
    """Every print the panel started: what, on which printer, when, and how it ended. Kept in one
    file that all OrcaSlicer windows share, newest last, capped at RUN_LOG_LIMIT entries."""

    def __init__(self, path):
        self.path, self._stamp, self.runs = path, None, []
        self._lock = threading.RLock()      # starts and endings arrive from different worker threads
        self.sync()

    def sync(self):
        with self._lock:
            self._sync()

    def _sync(self):
        stamp = file_stamp(self.path)
        if stamp == self._stamp:
            return
        self._stamp, self.runs = stamp, []
        try:
            with open(self.path, "r", encoding="utf-8") as handle:
                data = json.load(handle)
            self.runs = [run for run in data.get("runs", []) if isinstance(run, dict) and run.get("printer_id")]
        except (OSError, ValueError, AttributeError):
            pass

    def _save(self):
        try:
            write_private(self.path + ".tmp", json.dumps({"version": 1, "runs": self.runs[-RUN_LOG_LIMIT:]}, indent=1))
            os.replace(self.path + ".tmp", self.path)
            self._stamp = file_stamp(self.path)
        except OSError:
            pass                    # a history that cannot be written must never stop a print

    def start(self, printer, filename, item="", parts=None, kept=None, source="sliced", toolhead=None):
        with self._lock:
            return self._start(printer, filename, item, parts, kept, source, toolhead)

    def _start(self, printer, filename, item, parts, kept, source, toolhead):
        self._sync()
        run = {"id": uuid.uuid4().hex[:10], "started_at": time.time(), "printer_id": printer.get("id"),
               "printer": printer.get("name", ""), "model": printer.get("model", ""), "file": filename,
               "item": item or "", "parts": parts, "kept": kept, "source": source, "toolhead": toolhead,
               "ended_at": None, "result": None, "good": None}
        self.runs = (self.runs + [run])[-RUN_LOG_LIMIT:]
        self._save()
        return run["id"]

    def _open_run(self, printer_id):
        return next((run for run in reversed(self.runs) if run.get("printer_id") == printer_id), None)

    def end(self, printer_id, result, filename=""):
        """Close the newest run of this printer if it is still open and was this file."""
        with self._lock:
            return self._end(printer_id, result, filename)

    def _end(self, printer_id, result, filename):
        self._sync()
        run = self._open_run(printer_id)
        if run is None or run.get("result"):
            return False
        ours, theirs = os.path.basename(run.get("file") or ""), os.path.basename(filename or "")
        if ours and theirs and ours != theirs:
            return False            # the printer was printing something the panel did not start
        run["result"], run["ended_at"] = result, time.time()
        self._save()
        return True

    def good(self, printer_id, count):
        with self._lock:
            return self._good(printer_id, count)

    def _good(self, printer_id, count):
        self._sync()
        run = self._open_run(printer_id)
        if run is None or run.get("good") is not None:
            return False
        run["good"] = max(0, int(count))
        self._save()
        return True


class BedLog:
    """One small value per printer, kept in a file so it survives restarting OrcaSlicer and is the
    same in every OrcaSlicer window. Used for two things, each in its own file:

    beds: True = clear the bed first, False = the user said it is clear, absent = never seen.
    cleanups: the time old files were last removed automatically."""

    def __init__(self, path):
        self.path, self._stamp, self._beds = path, None, {}

    def _load(self):
        try:
            info = os.stat(self.path)
            stamp = (info.st_mtime_ns, info.st_size)
        except OSError:
            stamp = None
        if stamp == self._stamp:
            return
        self._stamp, self._beds = stamp, {}
        if stamp is None:
            return
        try:
            with open(self.path, "r", encoding="utf-8") as handle:
                data = json.load(handle)
            if isinstance(data, dict):
                self._beds = {str(key): value for key, value in data.items() if isinstance(value, (bool, int, float))}
        except (OSError, ValueError):
            pass

    def get(self, printer_id):
        self._load()
        return self._beds.get(printer_id)

    def set(self, printer_id, needs_clearing):
        self._load()
        if printer_id in self._beds and self._beds[printer_id] == needs_clearing:
            return
        self._beds[printer_id] = needs_clearing
        self._write()

    def forget(self, printer_id):
        self._load()
        if self._beds.pop(printer_id, None) is not None:
            self._write()

    def _write(self):
        temp = "%s.%d.tmp" % (self.path, os.getpid())
        try:
            write_private(temp, json.dumps(self._beds))
            os.replace(temp, self.path)
        except OSError:
            pass   # still right in this window; only the sharing and the restart memory are lost
        self._stamp = None


def bed_needs_clearing(known, status):
    """New value for a printer's bed flag after a status read, or None to leave it as it is.

    known: True, False, or None when this printer was never seen. A print that is running leaves a
    part on the bed. A printer first seen idle that reports a completed or cancelled last print is
    assumed to still hold it; after the user says the bed is clear, only a new print sets it again."""
    state = status.get("state")
    if state in ("printing", "paused"):
        # A print that has not extruded anything yet (heating, leveling) has put nothing on the
        # bed, so cancelling it there leaves the bed as it was. Unknown counts as something.
        return None if status.get("extruded_mm") == 0 else True
    if state == "idle" and known is None:
        return bool(status.get("last_result"))
    return None


STORE_FILE = "farm_send_printers.json"


VERSION_FILE = "farm_send_version.json"


def version_key(text):
    """(0, 3, 13) from "0.3.13"; () when it is not a version, so "dev" never counts as newer."""
    parts = str(text or "").strip().split(".")
    return tuple(int(part) for part in parts) if parts and all(part.isdigit() for part in parts) else ()


def newest_installed(storage_dir):
    """The newest Farm Send version recorded in the shared storage folder, or "". Every window
    records its own version there when it starts, and install.sh records the one it installs."""
    try:
        with open(os.path.join(storage_dir, VERSION_FILE), "r", encoding="utf-8") as handle:
            value = json.load(handle).get("version")
    except (OSError, ValueError, AttributeError):
        return ""
    return str(value) if version_key(value) else ""


def record_version(storage_dir, version):
    """Note this version in the storage folder unless a newer one is already there."""
    if not version_key(version) or version_key(newest_installed(storage_dir)) >= version_key(version):
        return
    try:
        write_private(os.path.join(storage_dir, VERSION_FILE), json.dumps({"version": version}))
    except OSError:
        pass


def data_dir_of(path):
    """OrcaSlicer's data folder, found from any path inside its orca_plugins folder.

    A plugin installed from a file lives in <data>/orca_plugins/<folder>/ with its storage in
    <data>/orca_plugins/plugin_data/<key>/. One installed from the Plugin Hub sits two levels
    deeper, under _subscribed/<user id>/. Walking up to "orca_plugins" works for both."""
    path = os.path.abspath(path or "")
    while True:
        parent = os.path.dirname(path)
        if os.path.basename(path) == "orca_plugins":
            return parent
        if not parent or parent == path:
            return ""
        path = parent


def saved_store_files(data_dir, plugin_file=""):
    """The printer file(s) belonging to THIS copy of the plugin.

    A copy installed from the Plugin Hub keeps its data in plugin_data/_subscribed/<user id>/<key>/
    and its code in _subscribed/<user id>/<key>/, so its own data folder is known exactly. A copy
    installed from a file uses plugin_data/<key>/. The two never read each other's printers:
    otherwise each would ask for network access to the other's addresses."""
    if not data_dir:
        return []
    base = os.path.join(data_dir, "orca_plugins", "plugin_data")
    parts = os.path.abspath(plugin_file or "").split(os.sep)
    if "_subscribed" in parts:
        at = parts.index("_subscribed")
        if len(parts) < at + 3:
            return []
        path = os.path.join(base, "_subscribed", parts[at + 1], parts[at + 2], STORE_FILE)
        return [path] if os.path.isfile(path) else []
    found = []
    try:
        names = sorted(os.listdir(base))
    except OSError:
        return found
    for name in names:
        path = os.path.join(base, name, STORE_FILE)
        if name != "_subscribed" and os.path.isfile(path):
            found.append(path)
    return found


def preset_to_printer(preset, fallback_name=""):
    """A printer entry from one OrcaSlicer printer preset (its settings as a dict), or None when
    the preset has no printer address or is not a printer type this plugin drives."""
    address = host_of(_first(preset.get("print_host")))
    if not address:
        return None
    inherits = _first(preset.get("inherits")) or ""
    label = _first(preset.get("name")) or fallback_name
    model = _first(preset.get("printer_model")) or re.sub(r"\s*\(?\d+(\.\d+)?\s*(mm)?\s*nozzle\)?.*$", "", inherits).strip()
    lowered = (model + " " + inherits + " " + label).lower()
    host_type = (_first(preset.get("host_type")) or "").lower()
    if "centauri carbon 2" in lowered:
        kind = KIND_CC2
    elif "snapmaker" in lowered or host_type in ("moonraker", "klipper"):
        kind = KIND_MOONRAKER
    else:
        return None
    key = _first(preset.get("printhost_apikey")) or ""
    return {"name": short_printer_name(label, inherits, model), "kind": kind, "address": address, "model": model,
            "access_code": key if kind == KIND_CC2 else "", "api_key": key if kind == KIND_MOONRAKER else "",
            "nozzle": first_number(preset.get("nozzle_diameter"))}


def presets_to_printers(preset_dir):
    """Printer entries from the printer preset files in one folder. Used only when OrcaSlicer's own
    preset list is not available; inside OrcaSlicer the live list is used instead, because a
    signed-in user has a second preset folder and only one of the two is in use."""
    found = []
    try:
        names = sorted(os.listdir(preset_dir))
    except OSError:
        return found
    for name in names:
        if not name.endswith(".json"):
            continue
        try:
            with open(os.path.join(preset_dir, name), "r", encoding="utf-8") as handle:
                preset = json.load(handle)
        except (OSError, ValueError):
            continue
        printer = preset_to_printer(preset, name[:-5]) if isinstance(preset, dict) else None
        if printer:
            found.append(printer)
    return found


def short_printer_name(label, inherits, model):
    """'Snapmaker U1 (0.4 nozzle) - #1' -> 'U1 #1', 'Elegoo Centauri Carbon 2 0.4 nozzle - CC1' -> 'CC1'.

    A user preset is normally named '<system preset> - <suffix>'; the suffix is the part that tells
    two printers apart, and it is what gets cut off in a narrow panel if the full name is kept."""
    suffix = ""
    if inherits and label.startswith(inherits):
        suffix = label[len(inherits):].strip(" -_:")
    if not suffix:
        return label
    if re.match(r"^[#\d]", suffix) and model:
        return "%s %s" % (model.split()[-1], suffix)
    return suffix


def _first(value):
    if isinstance(value, list):
        return value[0] if value else ""
    return value


def can_start(status):
    return status.get("state") == "idle"


# ======================================================================================
# app
SLICE_DIR = "slices"
SLICE_KEEP_S = 12 * 3600      # sliced copies of a window that is gone are dropped after this long
SLICE_TOUCH_S = 600
LIBRARY_DIR = "library"   # kept plates: <id>.gcode plus <id>.json describing it
STATUS_MIN_INTERVAL = 3.0
NEWER_CHECK_INTERVAL = 60.0    # seconds between looks for a newer installed Farm Send
STATUS_MIN_INTERVAL_CC2 = 8.0   # each CC2 poll is a full MQTT connect + register; be gentle
STORAGE_INTERVAL = 600.0        # how often each printer's stored files are counted
AUTO_CLEAN_INTERVAL = 86400.0   # automatic cleanup runs at most once a day per printer
BLOCKED_TEXT = "OrcaSlicer blocked network access to this printer. Approve the permission prompt, then it retries."


def _clock(when):
    return time.strftime("%H:%M", time.localtime(when))


def _short_duration(seconds):
    if seconds is None:
        return ""
    hours, minutes = int(seconds) // 3600, (int(seconds) % 3600) // 60
    return ("%dh%02dm" % (hours, minutes)) if hours else ("%dm" % max(1, minutes))


class WorkerPool:
    """A fixed set of background threads that run the plugin's network and file work.

    Why not start a thread per job: OrcaSlicer decides which plugin a thread belongs to at the
    moment the thread is started, from whichever plugin it believes is running right then. A
    message from a docked panel is delivered without that being set, so a thread started while
    handling one can be credited to another plugin: its printer requests then raise permission
    prompts in that other plugin's name, or are refused. Threads started from the plugin's own
    execute() call are credited correctly, so all workers are started there, once, and jobs are
    handed to them through a queue."""

    def __init__(self, size=16):
        self.size, self._jobs, self._threads = size, queue.Queue(), []
        self._lock = threading.Lock()

    @property
    def started(self):
        return bool(self._threads)

    def start(self):
        """Start the workers. Call only from a place where OrcaSlicer knows the plugin is running."""
        with self._lock:
            if self._threads:
                return
            for _ in range(self.size):
                thread = threading.Thread(target=self._run, daemon=True)
                thread.start()
                self._threads.append(thread)

    def submit(self, target, *args):
        if not self._threads:
            # Not started (tests, or a slice event before the panel was ever opened): run it now on
            # a thread of its own, as before.
            threading.Thread(target=target, args=args, daemon=True).start()
            return
        self._jobs.put((target, args))

    def _run(self):
        while True:
            target, args = self._jobs.get()
            try:
                target(*args)
            except Exception:
                pass   # a failing job must not take a worker down; each job reports its own errors


class FarmApp:
    def __init__(self, storage_dir, post, notify=None, preset_dirs=(), default_name=None, spawn=None,
                 read_presets=None, apply_presets=None, list_presets=None):
        self.store = PrinterStore(os.path.join(storage_dir, STORE_FILE))
        set_shared_dir(storage_dir)   # every OrcaSlicer window shares one client slot per CC2
        self.storage_dir = storage_dir
        self.newer = ""           # a newer Farm Send recorded in the storage folder than this window runs
        self.endings = {}         # printer id -> how its last print ended, as this window saw it
        self._newer_at = 0.0
        record_version(storage_dir, self.version())
        self.beds = BedLog(os.path.join(storage_dir, "farm_send_beds.json"))
        self.orders = OrderBook(os.path.join(storage_dir, "farm_send_orders.json"))
        self.runs = RunLog(os.path.join(storage_dir, "farm_send_runs.json"))
        self.cleaned = BedLog(os.path.join(storage_dir, "farm_send_cleaned.json"))   # last automatic cleanup per printer
        self.storage = {}         # printer id -> {count, bytes, oldest, removable, many, error}
        self._storage_at = {}
        self._storage_busy = set()
        self._post = post
        self._notify = notify or (lambda level, text: None)
        self.preset_dirs = list(preset_dirs)
        # list_presets() returns the printer presets OrcaSlicer has loaded right now, each as a dict
        # of its settings. UI thread only. When given, Import uses it instead of reading files.
        self._list_presets = list_presets
        self._default_name = default_name or (lambda: "")
        self._spawn = spawn or self._spawn_thread
        self.lock = threading.RLock()
        # One sliced plate per printer type, newest first. Each is the plugin's OWN copy of the G-code,
        # because OrcaSlicer rewrites its temp file on the next slice: without a copy, slicing for
        # the second printer type would destroy the plate sliced for the first.
        self.jobs = []
        # Each OrcaSlicer window keeps its sliced copies in a folder of its own, so a second window
        # starting up never removes the plates another window still holds.
        self.slice_root = os.path.join(storage_dir, SLICE_DIR)
        self.slice_dir = os.path.join(self.slice_root, uuid.uuid4().hex[:8])
        self._slice_touched = time.monotonic()
        self.library_dir = os.path.join(storage_dir, LIBRARY_DIR)
        self._library_cache, self._library_stamp = None, None
        self.chosen = {}        # printer type key -> id of the sliced plate its cards send
        self._saved_names = {}  # md5 of a kept plate -> its item name, refreshed with every snapshot
        self._clear_slice_dir()
        self.slicing = False
        self.status = {}          # printer id -> normalized status
        self._status_at = {}
        self._status_busy = set()
        self._watched = {}        # printer id -> last status in a watched state, for change notices
        self.notices = {}         # printer id -> {level, text, at}: the last change, kept on the card
        self.sends = {}           # printer id -> {active, text, percent, ok}
        self._cancel = {}
        # Slicing presets. read_presets() must run on the UI thread and returns the current selection
        # {"model", "printer", "process", "filaments"}; apply_presets(combo) switches to a saved one
        # and must run OFF the UI thread, because it waits for OrcaSlicer's own selection dialogs.
        self._read_presets = read_presets
        self._apply_presets = apply_presets
        self.current = None
        self.combo_note = {"text": "", "ok": True, "busy": False}

    def _clear_slice_dir(self, now=None):
        """Drop sliced copies left behind by windows that are gone. There is no way to ask whether
        another window is still open, so a folder counts as left behind once nothing in it has changed
        for SLICE_KEEP_S; an open window refreshes its folder while its panel is in use."""
        now = time.time() if now is None else now
        try:
            names = os.listdir(self.slice_root)
        except OSError:
            return
        for name in names:
            path = os.path.join(self.slice_root, name)
            try:
                if path == self.slice_dir or now - os.path.getmtime(path) < SLICE_KEEP_S:
                    continue
                if os.path.isdir(path):
                    for inner in os.listdir(path):
                        if inner.endswith(".gcode") or inner.endswith(".part"):
                            self._remove_file(os.path.join(path, inner))
                    os.rmdir(path)
                elif name.endswith(".gcode") or name.endswith(".part"):      # from before 0.3.3
                    self._remove_file(path)
            except OSError:
                pass

    def _touch_slice_dir(self):
        """Mark this window's sliced copies as still in use. Cheap, and at most every few minutes."""
        if time.monotonic() - self._slice_touched < SLICE_TOUCH_S:
            return
        self._slice_touched = time.monotonic()
        try:
            os.utime(self.slice_dir, None)
        except OSError:
            pass

    @staticmethod
    def _copy_file(source, target):
        """Plain read-then-write copy.

        shutil.copyfile is avoided on purpose: OrcaSlicer's plugin audit treats it as a read/write
        request on BOTH paths and prompts for write access to its temp G-code. Opening the source
        read-only needs just the read grant the plugin already declares."""
        with open(source, "rb") as reader, open(target, "wb") as writer:
            for block in iter(lambda: reader.read(1024 * 1024), b""):
                writer.write(block)

    @staticmethod
    def _remove_file(path):
        try:
            os.remove(path)
        except OSError:
            pass

    @staticmethod
    def _spawn_thread(target, *args):
        thread = threading.Thread(target=target, args=args, daemon=True)
        thread.start()
        return thread

    def post(self, message):
        try:
            self._post(message)
        except Exception:
            pass

    # ---- slicer events (called from the slicing worker thread: never touch the UI here) ----------
    def on_slice_started(self):
        with self.lock:
            self.slicing = True
        self.post({"command": "state", "slicing": True})

    def on_slice_done(self):
        with self.lock:
            self.slicing = False
        self.post_state()

    def on_gcode_exported(self, path, name=""):
        if not path or not path.lower().endswith(".gcode"):
            return
        # OrcaSlicer names each plate's file .<process id>.<plate index>.gcode, so "Slice all" on a
        # project with several plates arrives as one export per plate.
        match = re.search(r"\.(\d+)\.gcode$", os.path.basename(path), re.I)
        job = {"id": uuid.uuid4().hex[:10], "source": path, "path": "", "name": name or "", "captured_at": time.time(),
               "ready": False, "error": "", "stale": False, "meta": {}, "key": "", "plate": int(match.group(1)) + 1 if match else 1}
        with self.lock:
            self.slicing = False
            # Earlier failed or still-pending captures are superseded by this slice.
            self.jobs = [existing for existing in self.jobs if existing["ready"]]
            self.jobs.insert(0, job)
        self.post_state()
        self._spawn(self._read_job, job)

    def _read_job(self, job):
        """Copy the freshly sliced G-code into plugin storage, then read its metadata."""
        copy = os.path.join(self.slice_dir, job["id"] + ".gcode")
        try:
            os.makedirs(self.slice_dir, exist_ok=True)
            before = os.stat(job["source"])
            self._copy_file(job["source"], copy + ".part")
            after = os.stat(job["source"])
            if (before.st_size, before.st_mtime) != (after.st_size, after.st_mtime) or os.path.getsize(copy + ".part") != after.st_size:
                raise FarmError("The plate was sliced again while it was being read. The newer slice replaces it.")
            os.replace(copy + ".part", copy)
            meta = parse_gcode_meta(copy)
            if not meta.get("printer_model"):
                raise FarmError("The sliced G-code does not name a printer model, so it cannot be matched to a printer.")
            job["objects"], job["md5"] = count_objects(copy), file_md5(copy)
            replaced = []
            with self.lock:
                if job not in self.jobs:          # project closed or superseded while copying
                    replaced.append(copy)
                elif not self._farm_model(meta["printer_model"]):
                    # Sliced for a printer that is not in the farm (a printer used on its own): not
                    # Farm Send's business, so it is dropped without a trace and the plates held for
                    # the farm's printer types stay as they were.
                    self.jobs = [other for other in self.jobs if other is not job]
                    replaced.append(copy)
                else:
                    job["path"], job["meta"], job["key"] = copy, meta, model_key(meta["printer_model"])
                    # The newest slice of a plate replaces the older slice of that same plate for that
                    # printer type. Other plates of the project, and other printer types, are kept.
                    same = lambda other: other is not job and other["key"] == job["key"] and other.get("plate") == job["plate"]
                    replaced += [other["path"] for other in self.jobs if same(other)]
                    self.jobs = [other for other in self.jobs if not same(other)]
                    self.chosen[job["key"]] = job["id"]            # the plate just sliced is the one the cards send
                    job["ready"] = True
                    # Plates sliced earlier for other printer types are finished work. Re-arranging
                    # the bed for the next type is normal and must not flag them as out of date, so
                    # only the newest slice keeps tracking changes to the plate.
                    for other in self.jobs:
                        if other is not job:
                            other["settled"], other["stale"] = True, False
            for path in replaced:
                self._remove_file(path)
        except FarmError as error:
            job["error"] = str(error)
        except PermissionError:
            job["error"] = "OrcaSlicer blocked reading the sliced G-code. Approve the permission prompt and slice again."
        except OSError as error:
            job["error"] = "Cannot read the sliced G-code: %s" % (error.strerror or error)
        except Exception as error:      # never leave the panel stuck on "Reading..."
            job["error"] = "Could not read the sliced G-code: %s" % error
        if job["error"]:
            self._remove_file(copy + ".part")
            self._remove_file(copy)
        self.post_state()

    def _farm_model(self, model):
        """True when a printer in the farm is of this model."""
        return any(model_matches(model, printer.get("model")) for printer in self.store.printers)

    def mark_stale(self):
        """The plate on screen changed. Only the newest slice can be out of date because of it."""
        changed = False
        with self.lock:
            for job in self.jobs:
                if job["ready"] and not job.get("settled") and not job["stale"]:
                    job["stale"] = changed = True
        if changed:
            self.post_state()

    def project_closed(self):
        with self.lock:
            paths = [job["path"] for job in self.jobs if job["path"]]
            self.jobs, self.slicing = [], False
        for path in paths:
            self._remove_file(path)
        self.post_state()

    def _job_for(self, printer):
        """The sliced plate the printer's card sends: the one chosen for its type (the newest slice
        unless the user picked another plate), or None."""
        ready = [job for job in self.jobs if job["ready"] and model_matches(job["meta"].get("printer_model"), printer.get("model"))]
        for job in ready:
            if self.chosen.get(job["key"]) == job["id"]:
                return job
        return ready[0] if ready else None

    def _chosen_plate(self, key):
        """Of the plates held for one printer type, the one its cards send."""
        ready = [job for job in self.jobs if job["ready"] and job.get("key") == key]
        return next((job for job in ready if self.chosen.get(key) == job["id"]), ready[0] if ready else None)

    def _cmd_choose_plate(self, message):
        """Several plates are held for one printer type: send this one from the printer cards."""
        with self.lock:
            job = next((j for j in self.jobs if j["id"] == message.get("id") and j["ready"]), None)
            if job is not None:
                self.chosen[job["key"]] = job["id"]
        self.post_state()

    def _job_base_name(self, job):
        if not job["name"]:
            try:
                job["name"] = self._default_name() or ""
            except Exception:
                job["name"] = ""
        job["name"] = strip_model_suffix(job["name"])
        return job["name"] or "plate"

    def _job_view(self, job):
        meta = job["meta"]
        bits = []
        if meta.get("time_s") is not None:
            bits.append(_short_duration(meta["time_s"]))
        if meta.get("filament_g") is not None:
            bits.append("%.1f g" % meta["filament_g"])
        if meta.get("layers"):
            bits.append("%d layers" % meta["layers"])
        if meta.get("filament_type"):
            bits.append(meta["filament_type"].split(";")[0])
        if meta.get("size"):
            bits.append("%.1f MB" % (meta["size"] / 1048576.0))
        return {
            "id": job["id"], "ready": job["ready"], "error": job["error"], "stale": job["stale"], "key": job.get("key", ""),
            "plate": job.get("plate", 1),
            "objects": job.get("objects") or 0,
            "saved_as": self._saved_names.get(job.get("md5") or "", ""),
            "chosen": job is self._chosen_plate(job.get("key")),
            "display_name": self._job_base_name(job), "summary": " · ".join(bits),
            "printer_model": meta.get("printer_model", ""), "sliced_at": _clock(job["captured_at"]),
            "post_process": bool((meta.get("post_process") or "").strip()),
            "filaments": list(meta.get("filaments") or []),
            "presets": " \u00b7 ".join(part for part in (meta.get("process_preset"), meta.get("filament_preset")) if part),
            "printers": [p["name"] for p in self.store.printers if model_matches(meta.get("printer_model"), p.get("model"))],
        }

    def snapshot(self):
        with self.lock:
            # Another OrcaSlicer window may have saved printers, orders or library plates since.
            self.store.sync()
            self.orders.sync()
            stamp = file_stamp(self.library_dir)
            if stamp != self._library_stamp:
                self._library_stamp, self._library_cache = stamp, None
            self._saved_names = {e["md5"]: e.get("item", "") for e in self.library() if e.get("md5")}
            if self.jobs:
                self._touch_slice_dir()
            job_for = {}
            for printer in self.store.printers:
                match = self._job_for(printer)
                job_for[printer["id"]] = match["id"] if match else None
            return {
                "command": "state",
                "printers": [{k: p.get(k, "") for k in ("id", "name", "kind", "address", "model", "access_code", "api_key")}
                             for p in self.store.printers],
                "jobs": [self._job_view(job) for job in self.jobs],
                "job_for": job_for,
                # A slice for a printer outside the farm is not announced either.
                "slicing": self.slicing and (not (self.current or {}).get("model") or self._farm_model(self.current["model"])),
                "status": dict(self.status),
                "sends": dict(self.sends),
                "combos": self._combo_views(),
                "types": self._type_views(),
                "library": self._library_views(),
                "folders": self.library_folders(),
                "orders": self._order_views(),
                "order_plates": self._open_plates(),
                "toolhead_names": list(self.orders.toolhead_names),
                "storage": dict(self.storage),
                "cleanup": dict(self.store.cleanup, text=rule_text(self.store.cleanup)),
                "video_cleanup": dict(self.store.video_cleanup, text=rule_text(self.store.video_cleanup)),
                "version": self.version(),
                "newer": self.newer,
                "current": dict(self.current) if self.current else None,
                "combo_note": dict(self.combo_note),
                "can_switch": self._apply_presets is not None,
                "auto_open": self.store.auto_open,
            }

    def _combo_views(self):
        current = self.current or {}
        views = []
        for key, combo in sorted(self.store.combos.items(), key=lambda item: item[1].get("label", "").lower()):
            active = (current.get("printer") == combo.get("printer") and current.get("process") == combo.get("process")
                      and list(current.get("filaments") or [])[:len(combo.get("filaments") or [])] == list(combo.get("filaments") or []))
            views.append({"key": key, "label": combo.get("label", key), "printer": combo.get("printer", ""),
                          "process": combo.get("process", ""), "filaments": list(combo.get("filaments") or []),
                          "active": bool(active),
                          "printers": [p["name"] for p in self.store.printers if model_key(p.get("model")) == key]})
        return views

    def _type_views(self):
        """One row per printer type the user works with: its printers, its remembered presets and
        whether OrcaSlicer is set to that type right now. The panel adds the plate held for it."""
        current_key = model_key((self.current or {}).get("model") or "")
        combos = {view["key"]: view for view in self._combo_views()}
        rows = {}
        for printer in self.store.printers:
            key = model_key(printer.get("model"))
            if key:
                rows.setdefault(key, {"key": key, "label": printer.get("model", ""), "printers": []})["printers"].append(printer["name"])
        for key, combo in combos.items():
            rows.setdefault(key, {"key": key, "label": combo["label"], "printers": []})["label"] = combo["label"]
        for job in self.jobs:
            if job["ready"] and job.get("key") and not job.get("settled"):
                rows.setdefault(job["key"], {"key": job["key"], "label": job["meta"].get("printer_model", ""), "printers": []})
        for key, row in rows.items():
            row["combo"] = combos.get(key)
            row["selected"] = bool(current_key) and current_key == key
        return sorted(rows.values(), key=lambda row: row["label"].lower())

    def refresh_current(self):
        """Re-read OrcaSlicer's selected presets. UI thread only. Returns True when they changed."""
        if self._read_presets is None:
            return False
        try:
            current = self._read_presets()
        except Exception:
            return False
        if current != self.current:
            self.current = current
            return True
        return False

    def post_state(self):
        self.post(self.snapshot())

    # ---- panel messages (called on the UI thread: keep it quick) ------------------------------------
    def handle(self, message):
        command = (message or {}).get("command")
        handler = getattr(self, "_cmd_" + str(command), None)
        if handler is not None:
            handler(message)

    def _cmd_init(self, message):
        self.refresh_current()
        self.post_state()
        self.poll(force=True)

    def _cmd_poll(self, message):
        if self.refresh_current():
            self.post_state()
        self.poll()

    def report_text(self):
        """Facts worth pasting into a trouble report. No printer names, addresses, codes or keys."""
        lines = ["Farm Send %s" % globals().get("PLUGIN_VERSION", "dev"), "System: %s" % sys.platform,
                 "OrcaSlicer version: (Help > About)", ""]
        with self.lock:
            printers = [dict(p) for p in self.store.printers]
            status, sends = dict(self.status), dict(self.sends)
            lines.append("Library plates: %d, open orders: %d" % (len(self._library_views()), len(self.orders.orders)))
        lines.append("Printers: %d" % len(printers))
        for number, printer in enumerate(printers, 1):
            state = status.get(printer["id"]) or {}
            lines.append("%d. %s (%s): %s" % (number, printer.get("model") or "unknown model", printer.get("kind", ""),
                                              state.get("state_text") or state.get("state") or "not checked yet"))
            for label, text in (("error", state.get("error")), ("notice", (state.get("notice") or {}).get("text")),
                                ("last send", (sends.get(printer["id"]) or {}).get("text"))):
                if text:
                    lines.append("   %s: %s" % (label, text))
        return "\n".join(lines)

    def _cmd_runs(self, message):
        """The history of prints the panel started, newest first, with a count per printer."""
        self.runs.sync()
        rows, totals = [], {}
        for run in reversed(self.runs.runs[-300:]):
            took = (run["ended_at"] - run["started_at"]) if run.get("ended_at") else None
            rows.append({"when": time.strftime("%b %d %H:%M", time.localtime(run.get("started_at") or 0)),
                         "printer": run.get("printer", ""), "item": run.get("item") or run.get("file", ""),
                         "parts": run.get("kept") or run.get("parts"), "of": run.get("parts") if run.get("kept") else None,
                         "result": run.get("result") or "open", "good": run.get("good"),
                         "took": _short_duration(took) if took else "", "source": run.get("source", "")})
        for run in self.runs.runs:
            row = totals.setdefault(run.get("printer") or "?", {"started": 0, "finished": 0, "failed": 0})
            row["started"] += 1
            if run.get("result") == "finished":
                row["finished"] += 1
            elif run.get("result") in ("cancelled", "error", "stopped"):
                row["failed"] += 1
        self.post({"command": "runs", "runs": rows, "total": len(self.runs.runs),
                   "printers": [dict(name=name, **row) for name, row in sorted(totals.items())]})

    def _cmd_report(self, message):
        self.post({"command": "report", "text": self.report_text()})

    def _cmd_bed_cleared(self, message):
        """The user took the finished print off this printer's bed."""
        printer_id = message.get("id")
        with self.lock:
            if self.store.get(printer_id) is None:
                return
            self.beds.set(printer_id, False)
            counted = None
            if message.get("good") is not None:     # this bed held a plate of an order: how many came out good
                try:
                    counted = self.orders.count(printer_id, int(message.get("good")))
                    self.runs.good(printer_id, int(message.get("good")))
                except (TypeError, ValueError):
                    pass
            # Clearing the bed is the user saying they have seen how the print ended, so the note
            # about it leaves the card too. A printer that is free should not show its last file.
            self.notices.pop(printer_id, None)
            status = self.status.get(printer_id)
            if status is not None:
                status = dict(status, needs_clearing=False)
                status.pop("notice", None)
                self.status[printer_id] = status
        if status is not None:
            self.post({"command": "status", "id": printer_id, "status": status})
        if counted is not None:
            self.post_state()

    def _cmd_refresh(self, message):
        """Refresh button: ask now instead of waiting for the next timed poll. One printer, or all."""
        printer_id = message.get("id")
        self.poll(force=True, only=printer_id if isinstance(printer_id, str) and printer_id else None)

    def _set_combo_note(self, text, ok=True, busy=False):
        with self.lock:
            self.combo_note = {"text": text, "ok": ok, "busy": busy}

    def _cmd_save_combo(self, message):
        self.refresh_current()
        current = self.current or {}
        try:
            if not current.get("model"):
                raise FarmError("Select a printer preset in OrcaSlicer first")
            self.store.set_combo(current["model"], current.get("printer"), current.get("process"), current.get("filaments"))
            self._set_combo_note("Saved the current presets for %s." % current["model"])
        except FarmError as error:
            self._set_combo_note(str(error), ok=False)
        except OSError as error:
            self._set_combo_note("Could not save: %s" % (error.strerror or error), ok=False)
        self.post_state()

    def _cmd_delete_combo(self, message):
        try:
            self.store.remove_combo(message.get("key"))
            self._set_combo_note("")
        except OSError as error:
            self._set_combo_note("Could not save: %s" % (error.strerror or error), ok=False)
        self.post_state()

    def _cmd_load_combo(self, message):
        combo = self.store.combos.get(message.get("key"))
        if combo is None or self._apply_presets is None:
            return
        with self.lock:
            if self.combo_note.get("busy"):
                return
            self.combo_note = {"text": "Switching presets to %s..." % combo.get("label", ""), "ok": True, "busy": True}
        self.post_state()
        self._spawn(self._load_combo_worker, dict(combo))

    def _load_combo_worker(self, combo):
        try:
            skipped = self._apply_presets(combo) or []
            text = "Presets set for %s. Slice the plate." % combo.get("label", "")
            if skipped:
                text += " Not applied: %s." % "; ".join(skipped)
            self._set_combo_note(text, ok=not skipped)
        except Exception as error:
            self._set_combo_note("Presets not switched: %s" % error, ok=False)
        # The selection is re-read on the next poll, which runs on the UI thread.
        self.post_state()

    def _cmd_test_printer(self, message):
        try:
            printer = validate_printer(dict(message.get("printer") or {}, model=(message.get("printer") or {}).get("model") or "?"))
            info = make_client(printer, timeout=4).identify()
            model = info.get("model", "")
            text = "Connected: %s%s" % (model or "printer", (" · firmware " + info["firmware"]) if info.get("firmware") else "")
            self.post({"command": "form_result", "ok": True, "text": text, "model": model})
        except FarmError as error:
            self.post({"command": "form_result", "ok": False, "text": str(error)})
        except PermissionError:
            self.post({"command": "form_result", "ok": False, "text": "OrcaSlicer blocked the connection. Approve the prompt and test again."})

    def _cmd_save_printer(self, message):
        try:
            printer = self.store.upsert(message.get("printer") or {})
        except FarmError as error:
            self.post({"command": "form_result", "ok": False, "text": str(error)})
            return
        except OSError as error:
            self.post({"command": "form_result", "ok": False, "text": "Could not save: %s" % (error.strerror or error)})
            return
        with self.lock:
            self.status.pop(printer["id"], None)
            self._status_at.pop(printer["id"], None)
        self.post({"command": "form_result", "ok": True, "saved": True, "text": "Saved"})
        self.post_state()
        self.poll(force=True)

    def _cmd_delete_printer(self, message):
        printer_id = message.get("id")
        with self.lock:
            if self.sends.get(printer_id, {}).get("active"):
                return
            self.store.remove(printer_id)
            for table in (self.status, self._status_at, self.sends, self._watched, self.notices, self.storage, self._storage_at):
                table.pop(printer_id, None)
            self.cleaned.forget(printer_id)
            self.beds.forget(printer_id)
        self.post_state()

    def _cmd_import_presets(self, message):
        added, seen = [], {p["address"] for p in self.store.printers}
        candidates = []
        if self._list_presets is not None:
            try:
                candidates = [printer for printer in (preset_to_printer(preset) for preset in self._list_presets()) if printer]
            except Exception:
                candidates = []
        else:
            for folder in self.preset_dirs:
                candidates += presets_to_printers(folder)
        for candidate in candidates:
            if candidate["address"] in seen:
                # Already saved: only fill in a nozzle size it does not have yet.
                for known in self.store.printers:
                    if known["address"] == candidate["address"] and candidate.get("nozzle") and not known.get("nozzle"):
                        try:
                            self.store.upsert(dict(known, nozzle=candidate["nozzle"]))
                        except (FarmError, OSError):
                            pass
                continue
            try:
                self.store.upsert(candidate)
            except (FarmError, OSError):
                continue
            seen.add(candidate["address"])
            added.append("%s (%s)" % (candidate["name"], candidate["address"]))
        if added:
            text = "Added %d printer%s from your printer presets:" % (len(added), "" if len(added) == 1 else "s")
        else:
            text = ("No new printers found. Import reads user printer presets that have a printer address set, "
                    "for Centauri Carbon 2 and Snapmaker printers.")
        self.post({"command": "import_result", "text": text, "added": added})
        self.post_state()
        self.poll(force=True)

    def _cmd_cancel_send(self, message):
        event = self._cancel.get(message.get("id"))
        if event is not None:
            event.set()

    def _cmd_send(self, message):
        """Send to each listed printer the plate that was sliced for its type."""
        start = bool(message.get("start"))
        options = message.get("options") or {}
        work = []
        with self.lock:
            names = {}
            for printer_id in message.get("printer_ids") or []:
                printer = self.store.get(printer_id)
                if printer is None:
                    continue
                if self.sends.get(printer_id, {}).get("active"):
                    continue
                if start and self.beds.get(printer_id) and self.status.get(printer_id, {}).get("state") == "idle":
                    self._set_send(printer_id, False, "Not started: clear the bed, then click Bed cleared.", ok=False)
                    continue
                job = self._job_for(printer)
                if job is None:
                    other = next((j for j in self.jobs if j["ready"]), None)
                    if other is not None:
                        problem = "Blocked: no plate sliced for %s (the sliced plate is for %s)" % (
                            printer.get("model"), other["meta"].get("printer_model") or "another printer")
                    else:
                        problem = "No sliced plate for this printer type. Slice one first."
                    self._set_send(printer_id, False, problem, ok=False)
                    continue
                wrong = nozzle_mismatch(job["meta"].get("nozzle_diameter"), printer.get("nozzle"))
                if wrong:
                    self._set_send(printer_id, False, "Blocked: %s." % wrong, ok=False)
                    continue
                if job["id"] not in names:
                    # One file name per plate, fixed now so every printer of that type gets the same one.
                    meta = job["meta"]
                    parts = [self._job_base_name(job)]
                    if meta.get("filament_type"):
                        parts.append(meta["filament_type"].split(";")[0])
                    if meta.get("time_s"):
                        parts.append(_short_duration(meta["time_s"]))
                    names[job["id"]] = job_filename("_".join(parts))
                self._cancel[printer_id] = threading.Event()
                self._set_send(printer_id, True, "Preparing...", percent=0)
                work.append((dict(printer), {"path": job["path"], "name": names[job["id"]],
                                             "item": self._job_base_name(job),
                                             "slots": [f.get("slot") for f in job["meta"].get("filaments") or []]}))
        for printer, snapshot in work:
            self._spawn(self._send_worker, printer, snapshot, start, options)

    def _set_send(self, printer_id, active, text, percent=None, ok=None, started=False):
        entry = {"active": active, "text": text, "percent": percent, "ok": ok, "started": started, "at": time.monotonic()}
        with self.lock:
            self.sends[printer_id] = entry
        self.post({"command": "send", "id": printer_id, "send": entry})

    def _send_worker(self, printer, snapshot, start, options):
        printer_id, name = printer["id"], printer["name"]
        cancel = self._cancel.get(printer_id) or threading.Event()
        try:
            if not os.path.exists(snapshot["path"]):
                raise FarmError("That sliced plate was replaced by a newer slice. Send again.")
            client = make_client(printer)
            last = [0.0]

            def progress(sent, total):
                now = time.monotonic()
                if now - last[0] >= 0.25 or sent >= total:
                    last[0] = now
                    self._set_send(printer_id, True, "Uploading %d%%" % (100 * sent // max(1, total)), percent=100.0 * sent / max(1, total))

            self._set_send(printer_id, True, "Uploading 0%", percent=0)
            remote = client.upload(snapshot["path"], snapshot["name"], progress=progress, cancelled=cancel.is_set)
            if not start:
                self._set_send(printer_id, False, "Uploaded %s" % remote, ok=True)
                self._notify("info", "Farm Send: uploaded %s to %s" % (remote, name))
                return
            if cancel.is_set():
                raise FarmError("Cancelled after upload. The file is on the printer but was not started.")
            self._set_send(printer_id, True, "Starting print...", percent=100)
            status = client.status()
            if not can_start(status):
                raise FarmError("Uploaded, but not started: the printer is %s." % status.get("state_text", status.get("state")).lower())
            # Which filament numbers the file prints with: a CC2 is told which roll each one uses.
            how = client.start_print(remote, dict(options or {}, filament_slots=[s for s in snapshot.get("slots") or [] if s]))
            note = ""
            if how and how.startswith("roll"):
                note = " from %s" % how
            elif how == "standard":
                # Only Snapmaker firmware takes start options. Say so instead of implying they applied.
                note = ". This printer does not accept start options, so bed leveling and time-lapse follow its own settings"
            if snapshot.get("keep"):
                self._set_send(printer_id, True, "Started. Telling the printer to print %d part%s only..." % (
                    snapshot["keep"], "" if snapshot["keep"] == 1 else "s"), percent=100)
                try:
                    kept, total = client.keep_parts(snapshot["keep"], cancelled=cancel.is_set)
                except FarmError as error:
                    # Unconfirmed skips would print the whole plate, so stop it here.
                    try:
                        client.cancel_print()
                        stopped = "The print was cancelled."
                    except FarmError:
                        stopped = "CANCEL IT ON THE PRINTER: it may print the whole plate."
                    raise FarmError("Could not limit the plate to %d parts (%s). %s" % (snapshot["keep"], error, stopped))
                note = ": printing %d of %d parts%s" % (kept, total, note)
            if snapshot.get("order"):
                # Recorded only once the printer accepted the start, so a failed send never counts.
                self.orders.add_plate(snapshot["order"]["id"], printer_id, name, snapshot["order"]["parts"], remote)
                self.post_state()
            self.runs.start(printer, remote, item=snapshot.get("item") or snapshot.get("name") or "", parts=snapshot.get("parts"),
                            kept=snapshot.get("keep"), source=snapshot.get("source", "sliced"),
                            toolhead=snapshot.get("toolhead"))
            self._set_send(printer_id, False, "Started %s%s" % (remote, note), ok=True, started=True)
            self._notify("info", "Farm Send: %s started printing %s" % (name, remote))
        except FarmError as error:
            self._set_send(printer_id, False, str(error), ok=False)
            self._notify("error", "Farm Send: %s: %s" % (name, error))
        except PermissionError:
            self._set_send(printer_id, False, BLOCKED_TEXT, ok=False)
        except FileNotFoundError:
            # A re-slice for this printer type, or closing the project, removed the copy mid-upload.
            self._set_send(printer_id, False, "The sliced plate was replaced or closed during the upload. Send again.", ok=False)
        except OSError as error:
            self._set_send(printer_id, False, "Cannot read the sliced G-code: %s" % (error.strerror or error), ok=False)
        except Exception as error:  # never leave a card stuck on "Uploading"
            self._set_send(printer_id, False, "Unexpected error: %s" % error, ok=False)
        finally:
            self._cancel.pop(printer_id, None)
            self.poll(force=True, only=printer_id)
            self.check_storage(force=True, only=printer_id)

    # ---- library: plates kept for reprinting -------------------------------------------------------
    def library(self):
        """Every kept plate, read from the folder. Each plate is a G-code file with a small JSON file
        next to it; there is no index to drift out of step. A plate whose G-code is missing is skipped."""
        if self._library_cache is None:
            entries = []
            try:
                names = sorted(os.listdir(self.library_dir))
            except OSError:
                names = []
            for name in names:
                if not name.endswith(".json"):
                    continue
                try:
                    with open(os.path.join(self.library_dir, name), "r", encoding="utf-8") as handle:
                        entry = json.load(handle)
                except (OSError, ValueError):
                    continue
                path = os.path.join(self.library_dir, name[:-5] + ".gcode")
                if isinstance(entry, dict) and entry.get("id") == name[:-5] and os.path.isfile(path):
                    if "objects" not in entry:          # kept before part counts were recorded: count once
                        try:
                            entry["objects"] = count_objects(path)
                            write_private(os.path.join(self.library_dir, name), json.dumps(entry, indent=1))
                        except OSError:
                            entry.pop("objects", None)
                    entries.append(dict(entry, path=path))
            entries.sort(key=lambda entry: (str(entry.get("folder", "")).lower(), str(entry.get("item", "")).lower(),
                                            entry.get("parts") or 0))
            self._library_cache = entries
        return self._library_cache

    FOLDERS_FILE = "folders.json"   # folders the user made, so an empty one is still there
    FOLDER_SEP = " / "              # a folder inside a folder is a path: "Clips / Vertical"
    FOLDER_DEPTH = 4

    @classmethod
    def folder_path(cls, value):
        """A folder path as typed, tidied: parts trimmed, empty parts dropped, depth and length capped."""
        parts = [" ".join(part.split())[:40] for part in str(value or "").split("/")]
        return cls.FOLDER_SEP.join([part for part in parts if part][:cls.FOLDER_DEPTH])

    @classmethod
    def _under(cls, path, folder):
        """path is folder itself or somewhere inside it."""
        return path == folder or path.startswith(folder + cls.FOLDER_SEP)

    def library_folders(self):
        """Every folder, sorted: the ones made by hand plus any a kept plate names."""
        names = set()
        try:
            with open(os.path.join(self.library_dir, self.FOLDERS_FILE), "r", encoding="utf-8") as handle:
                names = {str(n) for n in json.load(handle) if isinstance(n, str) and n}
        except (OSError, ValueError, TypeError):
            pass
        names |= {e["folder"] for e in self.library() if e.get("folder")}
        for name in list(names):            # a folder's parents exist too
            parts = name.split(self.FOLDER_SEP)
            names |= {self.FOLDER_SEP.join(parts[:depth]) for depth in range(1, len(parts))}
        return sorted(names, key=str.lower)

    def _save_folders(self, names):
        os.makedirs(self.library_dir, exist_ok=True)
        write_private(os.path.join(self.library_dir, self.FOLDERS_FILE), json.dumps(sorted(set(names), key=str.lower)))
        self._library_cache = None

    def _move_folder(self, old, new):
        """Everything in folder old, at any depth, goes to the same place under new ("" = top level)."""
        moved = lambda path: (new + path[len(old):]).lstrip(" /") if new else path[len(old):].lstrip(" /")
        for entry in self.library():
            if self._under(entry.get("folder", ""), old):
                saved = {k: v for k, v in entry.items() if k != "path"}
                saved["folder"] = self.folder_path(moved(entry["folder"]))
                write_private(os.path.join(self.library_dir, entry["id"] + ".json"), json.dumps(saved, indent=1))
        self._library_cache = None
        return moved

    def _cmd_library_folder(self, message):
        """action add / rename / remove. name and new are full paths. Removing a folder keeps what is
        in it: its plates and its subfolders move up into the folder that held it."""
        name, new, action = self.folder_path(message.get("name")), self.folder_path(message.get("new")), message.get("action")
        folders = self.library_folders()
        try:
            if action == "add":
                if not name:
                    raise FarmError("Give the folder a name")
                self._save_folders(folders + [name])
            elif action in ("rename", "remove") and name in folders:
                if action == "rename":
                    if not new:
                        raise FarmError("Give the folder a name")
                    if self._under(new, name) and new != name:
                        raise FarmError("A folder cannot be moved into itself")
                else:
                    new = self.FOLDER_SEP.join(name.split(self.FOLDER_SEP)[:-1])      # its parent, or the top level
                moved = self._move_folder(name, new)
                kept = [f for f in folders if not self._under(f, name)]
                inside = [self.folder_path(moved(f)) for f in folders if self._under(f, name) and (action == "rename" or f != name)]
                self._save_folders([f for f in kept + inside if f])
            self.post({"command": "library_result", "ok": True, "text": ""})
        except FarmError as error:
            self.post({"command": "library_result", "ok": False, "text": str(error)})
        except OSError as error:
            self.post({"command": "library_result", "ok": False, "text": "Could not save: %s" % (error.strerror or error)})
        self.post_state()

    def _library_views(self):
        views = []
        for entry in self.library():
            bits = []
            if entry.get("time_s") is not None:
                bits.append(_short_duration(entry["time_s"]))
            if entry.get("filament_g") is not None:
                bits.append("%.1f g" % entry["filament_g"])
            if entry.get("layers"):
                bits.append("%d layers" % entry["layers"])
            views.append({"id": entry["id"], "item": entry.get("item", ""), "parts": entry.get("parts") or 0,
                          "folder": entry.get("folder", ""),
                          # A part count can be chosen when every part is labelled on its own.
                          "countable": bool(entry.get("parts")) and entry.get("objects") == entry.get("parts") and entry["parts"] > 1,
                          "key": entry.get("key", ""), "printer_model": entry.get("printer_model", ""),
                          "summary": " \u00b7 ".join(bits), "filaments": list(entry.get("filaments") or []),
                          "presets": entry.get("presets", ""), "saved_at": entry.get("saved_at") or 0,
                          "printers": [p["id"] for p in self.store.printers
                                       if model_matches(entry.get("printer_model"), p.get("model"))]})
        return views

    @staticmethod
    def _library_fields(message):
        """Item name, parts count and folder as typed, tidied. Raises FarmError when unusable."""
        item = " ".join(str(message.get("item") or "").split())[:80]
        folder = FarmApp.folder_path(message.get("folder"))
        try:
            parts = int(message.get("parts"))
        except (TypeError, ValueError):
            parts = 0
        if not item:
            raise FarmError("Give the item a name")
        if not 1 <= parts <= 9999:
            raise FarmError("Enter how many parts are on this plate")
        return item, parts, folder

    def _cmd_library_edit(self, message):
        """Rename a kept plate, correct its parts count, or move it to another folder."""
        entry = next((e for e in self.library() if e["id"] == message.get("id")), None)
        try:
            if entry is None:
                raise FarmError("That library plate no longer exists.")
            item, parts, folder = self._library_fields(message)
            saved = {k: v for k, v in entry.items() if k != "path"}
            saved.update(item=item, parts=parts, folder=folder)
            write_private(os.path.join(self.library_dir, entry["id"] + ".json"), json.dumps(saved, indent=1))
            self._library_cache = None
            self.post({"command": "library_result", "ok": True, "text": "Updated %s x%d." % (item, parts)})
        except FarmError as error:
            self.post({"command": "library_result", "ok": False, "text": str(error)})
        except OSError as error:
            self.post({"command": "library_result", "ok": False, "text": "Could not save: %s" % (error.strerror or error)})
        self.post_state()

    def _library_keep(self, job, item, parts, folder):
        """Copy one sliced plate into the library. Raises FarmError or OSError."""
        if job is None:
            raise FarmError("That plate is no longer here. Slice it again.")
        if job.get("stale"):
            raise FarmError("The plate changed after this slice. Slice again, then save.")
        os.makedirs(self.library_dir, exist_ok=True)
        entry_id = "%s-%s" % (time.strftime("%Y%m%d-%H%M%S"), job["id"][:6])
        target = os.path.join(self.library_dir, entry_id + ".gcode")
        self._copy_file(job["path"], target + ".part")
        os.replace(target + ".part", target)
        meta = job["meta"]
        entry = {"id": entry_id, "item": item, "parts": parts, "folder": folder, "key": job.get("key", ""),
                 "printer_model": meta.get("printer_model", ""), "time_s": meta.get("time_s"),
                 "filament_g": meta.get("filament_g"), "layers": meta.get("layers"),
                 "filaments": list(meta.get("filaments") or []), "nozzle_diameter": meta.get("nozzle_diameter"),
                 "presets": " \u00b7 ".join(x for x in (meta.get("process_preset"), meta.get("filament_preset")) if x),
                 "saved_at": time.time(), "size": os.path.getsize(target), "md5": file_md5(target),
                 "objects": count_objects(target)}
        # The description is written last: a plate only counts as kept once it is complete.
        write_private(os.path.join(self.library_dir, entry_id + ".json"), json.dumps(entry, indent=1))
        self._library_cache = None
        return entry

    def _cmd_library_save(self, message):
        """Keep the plate sliced just now, under an item name and with the number of parts on it."""
        with self.lock:
            job = next((j for j in self.jobs if j["id"] == message.get("job_id") and j["ready"]), None)
        try:
            item, parts, folder = self._library_fields(message)
            self._library_keep(job, item, parts, folder)
            self.post({"command": "library_result", "ok": True, "text": "Saved %s x%d to the library." % (item, parts)})
        except FarmError as error:
            self.post({"command": "library_result", "ok": False, "text": str(error)})
        except OSError as error:
            self.post({"command": "library_result", "ok": False, "text": "Could not save: %s" % (error.strerror or error)})
        self.post_state()

    def _cmd_library_save_all(self, message):
        """Keep several sliced plates in one go. rows: [{job_id, item, parts, folder}]. Every row is
        checked before anything is copied, so a typing mistake never leaves half of them saved."""
        rows = [row for row in (message.get("rows") or []) if isinstance(row, dict)]
        try:
            if not rows:
                raise FarmError("Nothing to save")
            todo = []
            with self.lock:
                jobs = {j["id"]: j for j in self.jobs if j["ready"]}
            for number, row in enumerate(rows, 1):
                job = jobs.get(row.get("job_id"))
                label = "Plate %s" % job["plate"] if job else "Row %d" % number
                try:
                    item, parts, folder = self._library_fields(row)
                    if job is None:
                        raise FarmError("That plate is no longer here. Slice it again.")
                    if job.get("stale"):
                        raise FarmError("The plate changed after this slice. Slice again, then save.")
                except FarmError as error:
                    raise FarmError("%s: %s" % (label, error))
                todo.append((job, item, parts, folder))
            for job, item, parts, folder in todo:
                self._library_keep(job, item, parts, folder)
            self.post({"command": "library_result", "ok": True,
                       "text": "Saved %d plate%s to the library." % (len(todo), "" if len(todo) == 1 else "s")})
        except FarmError as error:
            self.post({"command": "library_result", "ok": False, "text": str(error)})
        except OSError as error:
            self._library_cache = None
            self.post({"command": "library_result", "ok": False, "text": "Could not save: %s" % (error.strerror or error)})
        self.post_state()

    def _cmd_clear_slices(self, message):
        """Drop the sliced plates held for one printer type. Kept library plates are not touched."""
        key = message.get("key")
        with self.lock:
            gone = [job for job in self.jobs if job.get("key") == key and job["ready"]]
            self.jobs = [job for job in self.jobs if job not in gone]
            self.chosen.pop(key, None)
        for job in gone:
            self._remove_file(job["path"])
        self.post_state()

    def _cmd_library_delete(self, message):
        entry = next((e for e in self.library() if e["id"] == message.get("id")), None)
        if entry is not None:
            for name in (entry["id"] + ".json", entry["id"] + ".gcode"):   # description first: never half an entry
                try:
                    os.remove(os.path.join(self.library_dir, name))
                except OSError:
                    pass
            self._library_cache = None
        self.post_state()

    def _cmd_library_send(self, message):
        """Send a kept plate to the listed printers. toolhead: print a one-filament plate from this
        toolhead instead of the one it was sliced for (Snapmaker only). roll: the same for a Centauri
        Carbon 2, printing from this roll of its Canvas unit."""
        entry = next((e for e in self.library() if e["id"] == message.get("id")), None)
        self._library_start(entry, message.get("printer_ids") or [], bool(message.get("start")),
                            dict(message.get("options") or {}), message.get("toolhead"), keep=message.get("keep"),
                            roll=message.get("roll"))

    def _library_start(self, entry, printer_ids, start, options, toolhead=None, order_id=None, keep=None, roll=None):
        """keep: print only this many parts of the plate (Snapmaker / Klipper printers; the rest are
        skipped on the printer). None or the full count prints the whole plate."""
        work = []
        try:
            keep = int(keep) if keep is not None else None
        except (TypeError, ValueError):
            keep = None
        try:
            roll = int(roll) if roll else None
        except (TypeError, ValueError):
            roll = None
        if entry is not None and keep is not None and keep >= (entry.get("parts") or 0):
            keep = None
        with self.lock:
            name = None
            for printer_id in printer_ids:
                printer = self.store.get(printer_id)
                if printer is None or self.sends.get(printer_id, {}).get("active"):
                    continue
                problem = ""
                if entry is None:
                    problem = "That library plate no longer exists."
                elif not model_matches(entry.get("printer_model"), printer.get("model")):
                    problem = "Blocked: this plate was sliced for %s." % (entry.get("printer_model") or "another printer")
                elif nozzle_mismatch(entry.get("nozzle_diameter"), printer.get("nozzle")):
                    problem = "Blocked: %s." % nozzle_mismatch(entry.get("nozzle_diameter"), printer.get("nozzle"))
                elif start and self.beds.get(printer_id) and self.status.get(printer_id, {}).get("state") == "idle":
                    problem = "Not started: clear the bed, then click Bed cleared."
                mine = dict(options)
                fewer = keep if (keep and printer.get("kind") != KIND_CC2) else None
                if not problem and fewer:
                    if not start:
                        problem = "Not sent: a part count needs Start print, because the printer skips the other parts as it starts."
                    elif fewer < 1 or entry.get("objects") != entry.get("parts"):
                        problem = "Not started: this plate cannot print a part count."
                if not problem and start:
                    used = entry.get("filaments") or []
                    tools = (self.status.get(printer_id) or {}).get("tools") or []
                    if toolhead and printer.get("kind") != KIND_CC2:
                        if len(used) != 1:
                            problem = "Not started: only a one-filament plate can be moved to another toolhead."
                        else:
                            mine["toolhead_map"] = {used[0]["slot"]: int(toolhead)}
                            problem = toolhead_problem(tools, int(toolhead), used[0].get("type"))
                    elif roll and printer.get("kind") == KIND_CC2:
                        if len(used) != 1:
                            problem = "Not started: only a one-filament plate can be moved to another roll."
                        else:
                            mine["toolhead_map"] = {used[0]["slot"]: roll}
                            problem = toolhead_problem(tools, roll, used[0].get("type")).replace("toolhead", "roll")
                    else:
                        for filament in used:   # printing as sliced: every toolhead it uses must be usable
                            problem = problem or toolhead_problem(tools, filament.get("slot"), filament.get("type"))
                        # A CC2's roll colors are picked from a fixed list on the printer, so they are not compared.
                        if not problem and not mine.get("any_color") and printer.get("kind") != KIND_CC2:
                            # As sliced means the sliced color. A swapped spool is caught here unless the
                            # user confirmed the loaded color in the dialog.
                            for filament in used:
                                problem = problem or toolhead_color_problem(tools, filament.get("slot"), filament.get("color"))
                            if problem:
                                problem += ". Pick the toolhead with the right color, or confirm the loaded color"
                    if problem and not problem.startswith("Not started"):
                        problem = "Not started: %s." % problem
                if problem:
                    self._set_send(printer_id, False, problem, ok=False)
                    continue
                if name is None:
                    label = "%s_x%d" % (entry.get("item") or "plate", entry.get("parts") or 0)
                    if entry.get("time_s"):
                        label += "_" + _short_duration(entry["time_s"])
                    name = job_filename(label)
                self._cancel[printer_id] = threading.Event()
                self._set_send(printer_id, True, "Preparing...", percent=0)
                snapshot = {"path": entry["path"], "name": name, "item": entry.get("item", ""),
                            "slots": [f.get("slot") for f in entry.get("filaments") or []],
                            "parts": entry.get("parts"), "source": "order" if order_id else "library",
                            "toolhead": int(toolhead) if toolhead and printer.get("kind") != KIND_CC2 else None}
                if fewer:
                    snapshot["keep"] = fewer
                if order_id and start:
                    snapshot["order"] = {"id": order_id, "parts": fewer or entry.get("parts") or 0}
                work.append((dict(printer), snapshot, mine))
        for printer, snapshot, mine in work:
            self._spawn(self._send_worker, printer, snapshot, start, mine)

    # ---- orders: a quantity of one item, worked off plate by plate ---------------------------------
    def _order_views(self):
        items = {str(e.get("item", "")).lower() for e in self.library()}
        views = []
        for order in self.orders.orders:
            good, printing, remaining = OrderBook.totals(order)
            views.append({"id": order["id"], "item": order["item"], "quantity": order["quantity"],
                          "toolhead": order.get("toolhead"), "note": order.get("note", ""),
                          "good": good, "printing": printing, "remaining": remaining,
                          "in_library": order["item"].lower() in items,
                          "plates": [{k: plate.get(k) for k in ("printer_id", "printer_name", "parts", "state", "good")}
                                     for plate in order["plates"]]})
        return views

    def _open_plates(self):
        found = {}
        for order in self.orders.orders:
            for plate in order["plates"]:
                if plate.get("state") == "printing":
                    found[plate["printer_id"]] = {"order_id": order["id"], "item": order["item"], "parts": plate.get("parts") or 0}
        return found

    def _cmd_order_save(self, message):
        item = " ".join(str(message.get("item") or "").split())[:80]
        try:
            quantity = int(message.get("quantity"))
        except (TypeError, ValueError):
            quantity = 0
        try:
            toolhead = int(message.get("toolhead"))
        except (TypeError, ValueError):
            toolhead = None
        if item and 1 <= quantity <= 99999:
            self.orders.add(item, quantity, toolhead if toolhead in (1, 2, 3, 4) else None,
                            " ".join(str(message.get("note") or "").split())[:60])
        self.post_state()

    def _cmd_order_delete(self, message):
        self.orders.delete(message.get("id"))
        self.post_state()

    def _cmd_save_toolhead_names(self, message):
        names = message.get("names")
        if isinstance(names, list):
            self.orders.sync()
            self.orders.toolhead_names = ([" ".join(str(n).split())[:20] for n in names] + [""] * 4)[:4]
            self.orders.save()
        self.post_state()

    def _free_printers(self):
        busy = self._open_plates()
        return [p for p in self.store.printers
                if self.status.get(p["id"], {}).get("state") == "idle" and not self.beds.get(p["id"])
                and not self.sends.get(p["id"], {}).get("active") and p["id"] not in busy]

    def _cmd_order_plan(self, message):
        """Propose the next plates for an order across the printers that are free right now."""
        order = self.orders.get(message.get("id"))
        if order is None:
            return
        entries = [e for e in self.library() if str(e.get("item", "")).lower() == order["item"].lower()]
        with self.lock:
            free = self._free_printers()
        remaining = OrderBook.totals(order)[2]
        self.post({"command": "order_plan", "id": order["id"], "remaining": remaining,
                   "plan": plan_order(remaining, free, entries),
                   "usable": [p["id"] for p in free if plan_order(1, [p], entries)]})

    def _cmd_order_send(self, message):
        """Start the confirmed plates of a plan. Each pick is {printer_id, entry_id}."""
        order = self.orders.get(message.get("id"))
        if order is None:
            return
        entries = {e["id"]: e for e in self.library() if str(e.get("item", "")).lower() == order["item"].lower()}
        with self.lock:
            free = {p["id"] for p in self._free_printers()}
        for pick in message.get("picks") or []:
            entry = entries.get(pick.get("entry_id"))
            if entry is None or pick.get("printer_id") not in free:
                if self.store.get(pick.get("printer_id")):
                    self._set_send(pick["printer_id"], False, "Not started: the printer is no longer free. Plan the order again.", ok=False)
                continue
            free.discard(pick["printer_id"])
            self._library_start(entry, [pick["printer_id"]], True, dict(message.get("options") or {}),
                                order.get("toolhead"), order_id=order["id"], keep=pick.get("parts"))

    # ---- stored files and cleanup ------------------------------------------------------------------
    def check_storage(self, force=False, only=None):
        """Count the files stored on each printer, now and then. A slow, quiet background job."""
        now = time.monotonic()
        todo = []
        with self.lock:
            for printer in self.store.printers:
                printer_id = printer["id"]
                if only is not None and printer_id != only:
                    continue
                if printer_id in self._storage_busy or self.sends.get(printer_id, {}).get("active"):
                    continue
                if not force and printer_id in self._storage_at and now - self._storage_at[printer_id] < STORAGE_INTERVAL:
                    continue
                self._storage_busy.add(printer_id)
                self._storage_at[printer_id] = now
                todo.append(dict(printer))
        for printer in todo:
            self._spawn(self._storage_worker, printer)

    def _protected(self, printer_id):
        """Files a cleanup must not touch: whatever the printer is printing or has loaded."""
        status = self.status.get(printer_id) or {}
        return [status["filename"]] if status.get("filename") else []

    def _cleanup_block(self, printer):
        """Why old files cannot be removed from this printer right now, or ''."""
        status = self.status.get(printer["id"]) or {}
        state = status.get("state")
        if state in (None, "unknown", "offline"):
            return "printer is not reachable"
        if printer.get("kind") == KIND_CC2 and state != "idle":
            return "printer is busy; it is cleaned when idle"
        return ""

    def _video_summary(self, printer_id, videos):
        """Counts for a printer's time-lapse recordings; None when it keeps none we can list."""
        if videos is None:
            return None
        old = videos_to_clean(videos, self.store.video_cleanup, (self.status.get(printer_id) or {}).get("filename"))
        return dict(storage_summary(videos), removable=len(old), removable_bytes=sum(item.get("size") or 0 for item in old))

    def _set_storage(self, printer, files=None, error="", videos=False):
        """videos: the printer's recordings, None when it has none to list, False = unchanged."""
        printer_id = printer["id"]
        with self.lock:
            if self.store.get(printer_id) is None:
                return None
            before = self.storage.get(printer_id) or {}
            if files is None:
                entry = dict(before, error=error)
            else:
                entry = storage_summary(files)
                entry["videos"] = before.get("videos")
                entry["removable"] = len(files_to_clean(files, self.store.cleanup, self._protected(printer_id)))
                entry["many"] = printer.get("kind") == KIND_CC2 and entry["count"] >= CC2_MANY_FILES
                entry["error"] = ""
            if videos is not False:
                entry["videos"] = self._video_summary(printer_id, videos)
            self.storage[printer_id] = entry
        self.post({"command": "storage", "id": printer_id, "storage": entry})
        return entry

    def _storage_worker(self, printer):
        printer_id = printer["id"]
        entry = None
        try:
            client = make_client(printer, timeout=8)
            files = client.list_stored()
            try:
                videos = client.list_videos() if hasattr(client, "list_videos") else None
            except FarmError:
                videos = None      # the G-code count still stands
            entry = self._set_storage(printer, files, videos=videos)
        except FarmError as error:
            self._set_storage(printer, error=str(error))
        except Exception:
            self._set_storage(printer, error="Could not read the stored files")
        finally:
            with self.lock:
                self._storage_busy.discard(printer_id)
        # Automatic cleanup: only when the user switched it on, at most once a day per printer.
        if entry and entry.get("removable") and self.store.cleanup.get("auto"):
            with self.lock:
                last = self.cleaned.get(printer_id) or 0
                due = time.time() - last >= AUTO_CLEAN_INTERVAL and not self._cleanup_block(printer) \
                    and not self.sends.get(printer_id, {}).get("active")
                if due:
                    self.cleaned.set(printer_id, time.time())
                    self._cancel[printer_id] = threading.Event()
                    self._set_send(printer_id, True, "Removing old files...", percent=0)
            if due:
                self._cleanup_worker(printer, automatic=True)

    def _cmd_save_cleanup(self, message):
        try:
            if message.get("kind") == "videos":
                self.store.set_video_cleanup(message.get("rule"))
            else:
                self.store.set_cleanup(message.get("rule"))
        except OSError as error:
            self._notify("error", "Farm Send: could not save the cleanup rule: %s" % (error.strerror or error))
        self.post_state()
        self.check_storage(force=True)

    def _cmd_set_auto_open(self, message):
        try:
            self.store.set_auto_open(message.get("on"))
        except OSError as error:
            self._notify("error", "Farm Send: could not save the setting: %s" % (error.strerror or error))
        self.post_state()

    def _cmd_check_storage(self, message):
        self.check_storage(force=True)

    def _cmd_cleanup(self, message):
        """Remove the files the rule marks as old from each listed printer."""
        work = []
        with self.lock:
            for printer_id in message.get("printer_ids") or []:
                printer = self.store.get(printer_id)
                if printer is None or self.sends.get(printer_id, {}).get("active"):
                    continue
                block = self._cleanup_block(printer)
                if block:
                    self._set_send(printer_id, False, "Not cleaned: %s." % block, ok=False)
                    continue
                self._cancel[printer_id] = threading.Event()
                self._set_send(printer_id, True, "Checking stored files...", percent=0)
                work.append(dict(printer))
        for printer in work:
            self._spawn(self._video_cleanup_worker if message.get("kind") == "videos" else self._cleanup_worker, printer)

    def _video_cleanup_worker(self, printer):
        """Remove the time-lapse recordings the video rule marks as old. Only ever started by hand."""
        printer_id = printer["id"]
        cancel = self._cancel.get(printer_id) or threading.Event()
        try:
            client = make_client(printer, timeout=8)
            if not hasattr(client, "list_videos"):
                raise FarmError("Not cleaned: this printer's recordings cannot be listed.")
            status = client.status()      # asked now: the recording of the running print must be kept
            if printer.get("kind") == KIND_CC2 and status.get("state") != "idle":
                raise FarmError("Not cleaned: the printer is %s." % str(status.get("state_text") or status.get("state")).lower())
            videos = client.list_videos()
            if videos is None:
                raise FarmError("Not cleaned: this printer's recordings cannot be listed.")
            chosen = videos_to_clean(videos, self.store.video_cleanup, status.get("filename"))
            if not chosen:
                self._set_send(printer_id, False, "No recordings to remove: %s." % rule_text(self.store.video_cleanup), ok=True)
                self._set_storage(printer, videos=videos)
                return

            def progress(done, total):
                self._set_send(printer_id, True, "Removing old recordings: %d of %d" % (done, total), percent=100.0 * done / max(1, total))

            progress(0, len(chosen))
            client.delete_videos(chosen, progress=progress, cancelled=cancel.is_set)
            left = client.list_videos() or []     # count what is really gone
            still = {item["name"] for item in left}
            gone = [item for item in chosen if item["name"] not in still]
            freed = sum(item.get("size") or 0 for item in gone) / 1048576.0
            text = "Removed %d old recording%s (%.0f MB)" % (len(gone), "" if len(gone) == 1 else "s", freed)
            if len(gone) < len(chosen):
                text += ", %d could not be removed" % (len(chosen) - len(gone)) if not cancel.is_set() else ", stopped early"
            self._set_send(printer_id, False, text, ok=len(gone) == len(chosen) or cancel.is_set())
            self._set_storage(printer, videos=left)
        except FarmError as error:
            self._set_send(printer_id, False, str(error), ok=False)
        except PermissionError:
            self._set_send(printer_id, False, BLOCKED_TEXT, ok=False)
        except Exception as error:
            self._set_send(printer_id, False, "Unexpected error: %s" % error, ok=False)
        finally:
            self._cancel.pop(printer_id, None)

    def _cleanup_worker(self, printer, automatic=False):
        printer_id, name = printer["id"], printer["name"]
        cancel = self._cancel.get(printer_id) or threading.Event()
        try:
            client = make_client(printer, timeout=8)
            # Ask the printer again right now: what it is printing decides what must be kept.
            status = client.status()
            if printer.get("kind") == KIND_CC2 and status.get("state") != "idle":
                raise FarmError("Not cleaned: the printer is %s." % str(status.get("state_text") or status.get("state")).lower())
            protect = [status["filename"]] if status.get("filename") else []
            files = client.list_stored()
            chosen = files_to_clean(files, self.store.cleanup, protect)
            if not chosen:
                self._set_send(printer_id, False, "Nothing to remove: %s." % rule_text(self.store.cleanup), ok=True)
                self._set_storage(printer, files)
                return

            def progress(done, total):
                self._set_send(printer_id, True, "Removing old files: %d of %d" % (done, total), percent=100.0 * done / max(1, total))

            progress(0, len(chosen))
            client.delete_files([item["name"] for item in chosen], progress=progress, cancelled=cancel.is_set)
            # The printer says "ok" even when it kept a file, so count what is really gone.
            left = client.list_stored()
            still = {item["name"] for item in left}
            gone = [item for item in chosen if item["name"] not in still]
            freed = sum(item.get("size") or 0 for item in gone) / 1048576.0
            text = "Removed %d old file%s (%.0f MB)" % (len(gone), "" if len(gone) == 1 else "s", freed)
            if len(gone) < len(chosen):
                text += ", %d could not be removed" % (len(chosen) - len(gone)) if not cancel.is_set() else ", stopped early"
            self._set_send(printer_id, False, text, ok=len(gone) == len(chosen) or cancel.is_set())
            self._set_storage(printer, left)
            if automatic and gone:
                self._notify("info", "Farm Send: %s: %s" % (name, text.lower()))
        except FarmError as error:
            self._set_send(printer_id, False, str(error), ok=False)
        except PermissionError:
            self._set_send(printer_id, False, BLOCKED_TEXT, ok=False)
        except Exception as error:
            self._set_send(printer_id, False, "Unexpected error: %s" % error, ok=False)
        finally:
            self._cancel.pop(printer_id, None)

    # ---- status polling --------------------------------------------------------------------------
    @staticmethod
    def version():
        return str(globals().get("PLUGIN_VERSION", "dev"))

    def check_newer(self, now=None):
        """Look, at most once a minute, for a newer Farm Send installed since this window loaded it."""
        now = time.monotonic() if now is None else now
        if self._newer_at and now - self._newer_at < NEWER_CHECK_INTERVAL:
            return
        self._newer_at = now
        found = newest_installed(self.storage_dir)
        newer = found if version_key(found) > version_key(self.version()) and version_key(self.version()) else ""
        if newer != self.newer:
            self.newer = newer
            self.post_state()

    def poll(self, force=False, only=None):
        now = time.monotonic()
        todo = []
        with self.lock:
            for printer in self.store.printers:
                printer_id = printer["id"]
                if only is not None and printer_id != only:
                    continue
                if printer_id in self._status_busy:
                    continue
                interval = STATUS_MIN_INTERVAL_CC2 if printer.get("kind") == KIND_CC2 else STATUS_MIN_INTERVAL
                if not force and now - self._status_at.get(printer_id, 0) < interval:
                    continue
                self._status_busy.add(printer_id)
                todo.append(dict(printer))
        for printer in todo:
            self._spawn(self._status_worker, printer)
        if only is None:
            self.check_storage()
            self.check_newer(now)

    def _status_worker(self, printer):
        printer_id = printer["id"]
        try:
            status = make_client(printer, timeout=5).status()
        except FarmError as error:
            status = {"state": "offline", "state_text": "Offline", "detail": str(error), "filename": "", "progress": None,
                      "remaining_s": None, "nozzle": None, "bed": None, "errors": []}
        except PermissionError:
            status = {"state": "offline", "state_text": "Blocked", "detail": BLOCKED_TEXT, "filename": "", "progress": None,
                      "remaining_s": None, "nozzle": None, "bed": None, "errors": []}
        except Exception as error:
            status = {"state": "offline", "state_text": "Error", "detail": str(error), "filename": "", "progress": None,
                      "remaining_s": None, "nozzle": None, "bed": None, "errors": []}
        ended, ended_file = None, ""
        with self.lock:
            self._status_busy.discard(printer_id)
            self._status_at[printer_id] = time.monotonic()
            if self.store.get(printer_id) is None:
                return
            status["checked_at"] = time.time()   # wall clock, shown on the card
            event = None
            if status.get("state") in WATCHED_STATES:
                name = (self.store.get(printer_id) or printer).get("name") or "Printer"
                event = status_event(self._watched.get(printer_id), status, name)
                ended = run_result(self._watched.get(printer_id), status)
                ended_file = (self._watched.get(printer_id) or {}).get("filename") or ""
                self._watched[printer_id] = status
                note = self.notices.get(printer_id)
                if event:
                    self.notices[printer_id] = {"level": event[0], "text": event[1], "at": status["checked_at"],
                                                "state": status["state"]}
                elif note and note["state"] != status["state"] and status["state"] in ("idle", "printing"):
                    # Over once the printer moved on: the next print runs, a pause was resumed, an
                    # error was cleared. A note raised while printing stays for the rest of the print.
                    del self.notices[printer_id]
            if printer_id in self.notices:
                status["notice"] = self.notices[printer_id]
            change = bed_needs_clearing(self.beds.get(printer_id), status)
            if change is not None:
                self.beds.set(printer_id, change)
            status["needs_clearing"] = status.get("state") == "idle" and bool(self.beds.get(printer_id))
            if ended:
                self.endings[printer_id] = ended
            elif status.get("state") in ("printing", "paused"):
                self.endings.pop(printer_id, None)
            if status["needs_clearing"]:
                # How the print on the bed ended: seen ending in this window, else what the printer
                # reports about its last print. "" when neither is known.
                last = {"complete": "finished", "cancelled": "cancelled"}.get(status.get("last_result") or "", "")
                status["ended"] = self.endings.get(printer_id) or last
            self.status[printer_id] = status
            # "Started <file>" is only true while that print runs. Once the printer is idle again
            # (finished or cancelled) the line would be stale, so it is dropped.
            sent = self.sends.get(printer_id)
            stale = bool(sent and sent.get("started") and not sent.get("active") and status.get("state") == "idle"
                         and time.monotonic() - sent.get("at", 0) > 30)
            if stale:
                del self.sends[printer_id]
        if stale:
            self.post({"command": "send", "id": printer_id, "send": None})
        if ended:
            self.runs.end(printer_id, ended, ended_file)
        if event:
            self._notify(event[0], "Farm Send: %s" % event[1])
        self.post({"command": "status", "id": printer_id, "status": status})


